def login_page(title, body, **ctx):
    inner = render_template_string(body, **ctx)
    return render_template_string(LOGIN_BASE, title=title, css=CSS, body=inner, app_version=APP_VERSION)

def login_required(fn):
    @wraps(fn)
    def wrapped(*a,**k):
        return redirect(url_for("login")) if not session.get("user_id") else fn(*a,**k)
    return wrapped

def role_required(*roles):
    def decorator(fn):
        @wraps(fn)
        def wrapped(*a,**k):
            if not session.get("user_id"):
                return redirect(url_for("login"))
            if session.get("role") not in roles:
                flash("Non hai i permessi per questa operazione.")
                return redirect(url_for("home"))
            return fn(*a,**k)
        return wrapped
    return decorator

def log_action(db, action, product=None, details=""):
    db.execute("INSERT INTO audit_log(user_id,username,action,product_id,product_code,details) VALUES(?,?,?,?,?,?)",(
        session.get("user_id"), session.get("user","sconosciuto"), action,
        product["id"] if product else None,
        product["brand_code"] if product else None,
        details
    ))


BADGE_PREFIX = "TBSLOGIN:"

def badge_hash(token):
    return hashlib.sha256(token.encode("utf-8")).hexdigest()

def normalize_badge_payload(value):
    """Normalizza il contenuto QR/lettore senza alterare il token reale."""
    value=(value or "").strip()
    # Alcuni scanner mobili aggiungono virgolette tipografiche o delimitatori.
    value=value.strip("\"'“”‘’` \t\r\n")
    if value.upper().startswith(BADGE_PREFIX):
        value=value[len(BADGE_PREFIX):]
    return value.strip().strip("\"'“”‘’` \t\r\n")

def find_badge_user(db, payload):
    token=normalize_badge_payload(payload)
    if not token:
        return None
    return db.execute("SELECT * FROM users WHERE badge_token_hash=? AND active=1",(badge_hash(token),)).fetchone()

def start_user_session(db, user, audit_action="Login badge"):
    session.clear(); session.permanent=True
    session["user_id"]=user["id"]; session["user"]=user["username"]; session["role"]=user["role"]
    log_action(db,audit_action); db.commit()

def badge_scanner_html(target_url, button_label="Accedi con badge", auto_start=True, privacy_blur=False):
    """Scanner QR compatibile con Safari macOS/iPhone, Chrome ed Edge."""
    auto_value = "true" if auto_start else "false"
    privacy_class = " badge-privacy" if privacy_blur else ""
    privacy_overlay = """
  <div class="badge-privacy-overlay" aria-hidden="true">
    <div class="badge-lock-icon">🔒</div>
    <strong>Avvicina il badge</strong>
    <span>La fotocamera è attiva</span>
  </div>""" if privacy_blur else ""
    html = r'''<div class="card badge-login__PRIVACY_CLASS__" style="max-width:520px;margin:20px auto;text-align:center">
<h2 style="margin-top:0">📷 Inquadra il badge</h2>
<p class="muted">La fotocamera si avvia automaticamente. Inquadra il QR nel riquadro.</p>
<style>
.badge-privacy{background:linear-gradient(145deg,#15130d,#080808)!important;border:1px solid rgba(232,190,91,.48)!important;color:#fff!important}
.badge-privacy h2{color:#fff!important}
.badge-privacy .muted{color:#d6d0c5!important}
.badge-camera-shell{position:relative;overflow:hidden;border-radius:18px;background:#050505;min-height:250px;border:1px solid rgba(232,190,91,.44)}
.badge-privacy #badgeVideo{filter:blur(14px) brightness(.38) saturate(.72);transform:scale(1.08);transition:filter .25s ease,transform .25s ease}
.badge-privacy #badgeGuide{border-color:#e5bd5d!important;box-shadow:0 0 0 999px rgba(0,0,0,.30),0 0 22px rgba(229,189,93,.28)!important}
.badge-privacy-overlay{position:absolute;inset:0;z-index:4;display:flex;flex-direction:column;align-items:center;justify-content:center;pointer-events:none;background:linear-gradient(180deg,rgba(0,0,0,.08),rgba(0,0,0,.28));text-align:center}
.badge-privacy-overlay .badge-lock-icon{display:grid;width:68px;height:68px;place-items:center;margin-bottom:12px;border:1px solid rgba(239,202,112,.68);border-radius:22px;background:rgba(4,4,4,.72);font-size:31px;box-shadow:0 0 28px rgba(218,174,70,.22)}
.badge-privacy-overlay strong{color:#fff;font-size:24px;font-family:Georgia,"Times New Roman",serif;text-shadow:0 2px 12px #000}
.badge-privacy-overlay span{margin-top:6px;color:#efd792;font-size:13px;font-weight:800;letter-spacing:.06em;text-transform:uppercase}
.badge-privacy.badge-success #badgeVideo{filter:blur(5px) brightness(.58);transform:scale(1.04)}
.badge-privacy.badge-success .badge-privacy-overlay{opacity:0;transition:opacity .18s ease}
@media(max-width:560px){
 .badge-privacy-overlay .badge-lock-icon{width:58px;height:58px;font-size:27px}
 .badge-privacy-overlay strong{font-size:21px}
}
</style>
<div class="badge-camera-shell">
  <video id="badgeVideo" playsinline webkit-playsinline muted autoplay style="width:100%;height:300px;object-fit:cover;display:block;background:#111"></video>
  <canvas id="badgeCanvas" style="display:none"></canvas>
  <div id="badgeGuide" style="position:absolute;z-index:3;inset:16%;border:3px solid rgba(255,255,255,.9);border-radius:16px;box-shadow:0 0 0 999px rgba(0,0,0,.28);pointer-events:none"></div>
  __PRIVACY_OVERLAY__
</div>
<form id="badgeForm" method="post" action="__TARGET__" style="margin-top:12px">
  <input id="badgePayload" name="badge_payload" placeholder="Codice badge o lettore USB" autocomplete="off">
  <button type="button" id="badgeMainButton" style="margin-top:8px">__LABEL__</button>
  <button type="submit" id="badgeManualSubmit" class="secondary" style="margin-top:8px;display:none">Invia codice</button>
</form>
<div class="actions" style="justify-content:center">
  <button type="button" class="secondary" id="stopBadgeCamera" style="display:none">Ferma fotocamera</button>
</div>
<p id="badgeStatus" class="muted" aria-live="polite">Fotocamera non avviata.</p>
</div>
<script>
(function(){{
  const video=document.getElementById('badgeVideo');
  const canvas=document.getElementById('badgeCanvas');
  const ctx=canvas.getContext('2d',{{willReadFrequently:true}});
  const start=document.getElementById('badgeMainButton');
  const manualSubmit=document.getElementById('badgeManualSubmit');
  const stop=document.getElementById('stopBadgeCamera');
  const field=document.getElementById('badgePayload');
  const form=document.getElementById('badgeForm');
  const status=document.getElementById('badgeStatus');
  const guide=document.getElementById('badgeGuide');
  let stream=null,running=false,submitted=false,scanTimer=null,jsQRPromise=null;

  function loadJsQR(){{
    if(window.jsQR) return Promise.resolve(window.jsQR);
    if(jsQRPromise) return jsQRPromise;
    jsQRPromise=new Promise((resolve,reject)=>{{
      const script=document.createElement('script');
      const sources=[
        'https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.min.js',
        'https://unpkg.com/jsqr@1.4.0/dist/jsQR.js'
      ];
      let index=0;
      const tryNext=()=>{
        if(index>=sources.length){reject(new Error('Impossibile caricare il lettore QR'));return;}
        const script=document.createElement('script');
        script.src=sources[index++];
        script.async=true;
        script.onload=()=>window.jsQR?resolve(window.jsQR):tryNext();
        script.onerror=tryNext;
        document.head.appendChild(script);
      };
      tryNext();
    }});
    return jsQRPromise;
  }}

  function explainError(err){{
    const name=(err&&err.name)||'';
    if(!window.isSecureContext) return 'Apri il gestionale tramite HTTPS: Safari blocca la fotocamera su connessioni non sicure.';
    if(name==='NotAllowedError'||name==='PermissionDeniedError') return 'Safari non ha consentito l’avvio automatico. Premi il pulsante principale oppure abilita Fotocamera nelle impostazioni del sito.';
    if(name==='NotFoundError'||name==='DevicesNotFoundError') return 'Nessuna fotocamera disponibile su questo dispositivo.';
    if(name==='NotReadableError'||name==='TrackStartError') return 'La fotocamera è occupata da un’altra applicazione. Chiudila e riprova.';
    if(name==='OverconstrainedError'||name==='ConstraintNotSatisfiedError') return 'La fotocamera non supporta le impostazioni richieste. Riprova.';
    if(name==='AbortError') return 'Avvio della fotocamera interrotto. Premi nuovamente “Avvia fotocamera”.';
    return 'Impossibile avviare la fotocamera: '+((err&&err.message)||'errore sconosciuto')+'.';
  }}

  async function halt(){{
    running=false;
    if(scanTimer){{cancelAnimationFrame(scanTimer);scanTimer=null;}}
    if(stream) stream.getTracks().forEach(t=>t.stop());
    stream=null;
    try{{video.pause();video.srcObject=null;}}catch(e){{}}
    stop.style.display='none';
    start.style.display='inline-block';
    start.disabled=false;
  }}

  function submitBadge(value){{
    if(submitted) return;
    const clean=(value||'').trim();
    if(!clean) return;
    submitted=true;
    field.value=clean;
    status.textContent='✓ Badge letto. Accesso in corso…';
    guide.style.borderColor='#34d399';
    const badgeCard=video.closest('.badge-login');
    if(badgeCard) badgeCard.classList.add('badge-success');
    halt().finally(()=>form.submit());
  }}

  function scanFrame(){{
    if(!running||submitted) return;
    if(video.readyState>=2 && video.videoWidth>0 && video.videoHeight>0 && window.jsQR){{
      const maxWidth=900;
      const scale=Math.min(1,maxWidth/video.videoWidth);
      canvas.width=Math.max(1,Math.round(video.videoWidth*scale));
      canvas.height=Math.max(1,Math.round(video.videoHeight*scale));
      ctx.drawImage(video,0,0,canvas.width,canvas.height);
      try{{
        const image=ctx.getImageData(0,0,canvas.width,canvas.height);
        const code=window.jsQR(image.data,image.width,image.height,{{inversionAttempts:'attemptBoth'}});
        if(code&&code.data){{submitBadge(code.data);return;}}
      }}catch(e){{}}
    }}
    scanTimer=requestAnimationFrame(scanFrame);
  }}

  async function begin(){{
    if(running) return;
    submitted=false;
    guide.style.borderColor='rgba(255,255,255,.9)';
    if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){{
      status.textContent='Questo browser non permette l’accesso alla fotocamera. Usa password o lettore USB.';
      return;
    }}
    try{{
      start.disabled=true;
      status.textContent='Richiesta accesso alla fotocamera…';
      await halt();
      const isIPad=/iPad/i.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
      const preferredFacing=isIPad?'user':'environment';
      const constraints={{audio:false,video:{{facingMode:{{ideal:preferredFacing}},width:{{ideal:1280}},height:{{ideal:720}}}}}};
      try{{
        stream=await navigator.mediaDevices.getUserMedia(constraints);
      }}catch(firstError){{
        if(firstError && (firstError.name==='OverconstrainedError'||firstError.name==='ConstraintNotSatisfiedError')){{
          stream=await navigator.mediaDevices.getUserMedia({{audio:false,video:true}});
        }}else throw firstError;
      }}
      video.srcObject=stream;
      video.setAttribute('playsinline','');
      video.setAttribute('webkit-playsinline','');
      await video.play();
      running=true;
      start.style.display='none';
      stop.style.display='inline-block';
      status.textContent='Fotocamera attiva. Preparazione lettore QR…';
      try{
        await loadJsQR();
        status.textContent='Fotocamera attiva. Inquadra il QR dentro il riquadro.';
        scanTimer=requestAnimationFrame(scanFrame);
      }catch(readerError){
        status.textContent='Fotocamera attiva, ma il lettore QR non è disponibile. Usa il codice o il lettore USB.';
        console.error('Badge QR reader error',readerError);
      }
    }}catch(err){{
      await halt();
      status.textContent=explainError(err);
      console.error('Badge camera error',err);
    }}finally{{
      start.disabled=false;
    }}
  }}

  start.addEventListener('click',()=>{{
    const value=field.value.trim();
    if(value){{submitBadge(value);return;}}
    begin();
  }});
  stop.addEventListener('click',halt);
  form.addEventListener('submit',(event)=>{{
    const value=field.value.trim();
    if(!value){{
      event.preventDefault();
      status.textContent='Inquadra il QR oppure inserisci il codice del badge.';
      begin();
    }}
  }});
  field.addEventListener('input',()=>{{
    const v=field.value.trim();
    manualSubmit.style.display=v?'inline-block':'none';
    if(v.length>20){{clearTimeout(field._t);field._t=setTimeout(()=>submitBadge(v),120);}}
  }});
  window.addEventListener('pagehide',halt);
  window.addEventListener('beforeunload',halt);
  if(__AUTO__){{
    const autoBegin=()=>{{
      status.textContent='Avvio automatico della fotocamera…';
      begin();
    }};
    if(document.readyState==='loading'){{
      window.addEventListener('DOMContentLoaded',autoBegin,{{once:true}});
    }}else{{
      setTimeout(autoBegin,120);
    }}
  }}
}})();
</script>'''
    return (html
        .replace("__TARGET__", target_url)
        .replace("__LABEL__", button_label)
        .replace("__AUTO__", auto_value)
        .replace("__PRIVACY_CLASS__", privacy_class)
        .replace("__PRIVACY_OVERLAY__", privacy_overlay)
        .replace("{{", "{")
        .replace("}}", "}")
    )

def product_scanner_html(target_url):
    """Scanner QR prodotti: lettore nativo Android + fallback jsQR."""
    html=badge_scanner_html(target_url,"Cerca prodotto",auto_start=True)
    old_vars = "  let stream=null,running=false,submitted=false,scanTimer=null,jsQRPromise=null;"
    new_vars = """  let stream=null,running=false,submitted=false,scanTimer=null,jsQRPromise=null;
  let productDetector=null,lastProductScanAt=0,detectorBusy=false;"""
    if old_vars not in html:
        raise RuntimeError("Variabili scanner non trovate")
    html=html.replace(old_vars,new_vars,1)

    old_scan = r"""  function scanFrame(){
    if(!running||submitted) return;
    if(video.readyState>=2 && video.videoWidth>0 && video.videoHeight>0 && window.jsQR){
      const maxWidth=900;
      const scale=Math.min(1,maxWidth/video.videoWidth);
      canvas.width=Math.max(1,Math.round(video.videoWidth*scale));
      canvas.height=Math.max(1,Math.round(video.videoHeight*scale));
      ctx.drawImage(video,0,0,canvas.width,canvas.height);
      try{
        const image=ctx.getImageData(0,0,canvas.width,canvas.height);
        const code=window.jsQR(image.data,image.width,image.height,{inversionAttempts:'attemptBoth'});
        if(code&&code.data){submitBadge(code.data);return;}
      }catch(e){}
    }
    scanTimer=requestAnimationFrame(scanFrame);
  }"""

    new_scan = r"""  function decodeCanvas(){
    if(!window.jsQR)return null;
    try{
      const image=ctx.getImageData(0,0,canvas.width,canvas.height);
      const code=window.jsQR(image.data,image.width,image.height,{inversionAttempts:'attemptBoth'});
      return code&&code.data?code.data:null;
    }catch(e){return null;}
  }

  async function detectNative(){
    if(!productDetector||detectorBusy||!running||submitted)return null;
    detectorBusy=true;
    try{
      const results=await productDetector.detect(video);
      return results&&results.length&&results[0].rawValue?results[0].rawValue:null;
    }catch(e){
      return null;
    }finally{
      detectorBusy=false;
    }
  }

  async function scanFrame(){
    if(!running||submitted)return;

    const now=performance.now();
    if(now-lastProductScanAt<85){
      scanTimer=requestAnimationFrame(scanFrame);
      return;
    }
    lastProductScanAt=now;

    if(video.readyState>=2&&video.videoWidth>0&&video.videoHeight>0){
      const nativeValue=await detectNative();
      if(nativeValue){submitBadge(nativeValue);return;}

      if(window.jsQR){
        const vw=video.videoWidth, vh=video.videoHeight;

        // Prima analizza la zona centrale, ingrandita: è la più efficace
        // con etichette QR da 13 mm.
        const cropRatio=.56;
        const sw=Math.round(vw*cropRatio);
        const sh=Math.round(vh*cropRatio);
        const sx=Math.round((vw-sw)/2);
        const sy=Math.round((vh-sh)/2);
        const targetWidth=Math.min(1400,Math.max(1000,sw*1.35));

        canvas.width=Math.max(1,Math.round(targetWidth));
        canvas.height=Math.max(1,Math.round(targetWidth*sh/sw));
        ctx.imageSmoothingEnabled=false;
        ctx.drawImage(video,sx,sy,sw,sh,0,0,canvas.width,canvas.height);

        let value=decodeCanvas();
        if(value){submitBadge(value);return;}

        // Secondo tentativo sul fotogramma completo.
        const fullWidth=Math.min(1200,vw);
        canvas.width=Math.max(1,Math.round(fullWidth));
        canvas.height=Math.max(1,Math.round(fullWidth*vh/vw));
        ctx.drawImage(video,0,0,vw,vh,0,0,canvas.width,canvas.height);

        value=decodeCanvas();
        if(value){submitBadge(value);return;}
      }
    }
    scanTimer=requestAnimationFrame(scanFrame);
  }"""

    if old_scan not in html:
        raise RuntimeError("Funzione scanFrame originale non trovata")
    html=html.replace(old_scan,new_scan,1)

    old_begin_part = """      video.srcObject=stream;
      video.setAttribute('playsinline','');
      video.setAttribute('webkit-playsinline','');
      await video.play();
      running=true;
      start.style.display='none';
      stop.style.display='inline-block';
      status.textContent='Fotocamera attiva. Preparazione lettore QR…';
      try{
        await loadJsQR();
        status.textContent='Fotocamera attiva. Inquadra il QR dentro il riquadro.';
        scanTimer=requestAnimationFrame(scanFrame);
      }catch(readerError){
        status.textContent='Fotocamera attiva, ma il lettore QR non è disponibile. Usa il codice o il lettore USB.';
        console.error('Product QR reader error',readerError);
      }"""

    new_begin_part = """      video.srcObject=stream;
      video.setAttribute('playsinline','');
      video.setAttribute('webkit-playsinline','');
      await video.play();

      // Prova ad attivare la messa a fuoco continua senza bloccare
      // i dispositivi che non la supportano.
      try{
        const track=stream.getVideoTracks()[0];
        const caps=track&&track.getCapabilities?track.getCapabilities():{};
        const advanced={};
        if(caps.focusMode&&caps.focusMode.includes('continuous'))advanced.focusMode='continuous';
        if(caps.exposureMode&&caps.exposureMode.includes('continuous'))advanced.exposureMode='continuous';
        if(Object.keys(advanced).length)await track.applyConstraints({advanced:[advanced]});
      }catch(e){}

      try{
        if('BarcodeDetector' in window){
          const formats=await BarcodeDetector.getSupportedFormats();
          if(formats.includes('qr_code'))productDetector=new BarcodeDetector({formats:['qr_code']});
        }
      }catch(e){productDetector=null;}

      running=true;
      start.style.display='none';
      stop.style.display='inline-block';
      status.textContent='Fotocamera attiva. Avvicina il QR finché è nitido.';

      // Il lettore nativo parte subito. jsQR viene caricato come seconda lettura.
      loadJsQR().catch(readerError=>console.error('Product QR fallback error',readerError));
      scanTimer=requestAnimationFrame(scanFrame);"""

    if old_begin_part not in html:
        raise RuntimeError("Blocco avvio scanner non trovato")
    html=html.replace(old_begin_part,new_begin_part,1)

    old_submit = """  function submitBadge(value){
    if(submitted) return;
    const clean=(value||'').trim();
    if(!clean) return;
    submitted=true;
    field.value=clean;
    status.textContent='✓ QR letto. Ricerca del prodotto…';
    guide.style.borderColor='#34d399';
    const badgeCard=video.closest('.badge-login');
    if(badgeCard) badgeCard.classList.add('badge-success');
    halt().finally(()=>form.submit());
  }"""

    new_submit = """  async function submitBadge(value){
    if(submitted)return;
    const clean=(value||'').trim();
    if(!clean)return;
    submitted=true;
    field.value=clean;
    status.textContent='Verifica prodotto…';
    guide.style.borderColor='#d6ae58';
    try{
      const response=await fetch('/products/scan-check?code='+encodeURIComponent(clean),{
        cache:'no-store',
        headers:{'Accept':'application/json'}
      });
      let data={};try{data=await response.json()}catch(e){}
      if(!response.ok||!data.ok){
        guide.style.borderColor='#ef4444';
        status.textContent='✕ Prodotto non trovato: '+clean;
        submitted=false;
        setTimeout(()=>{
          guide.style.borderColor='rgba(255,255,255,.9)';
          status.textContent='Inquadra un altro QR.';
        },1300);
        return;
      }
      try{if(navigator.vibrate)navigator.vibrate(70)}catch(e){}
      guide.style.borderColor='#34d399';
      status.textContent='✓ '+data.brand_code+' riconosciuto. Apertura…';
      await halt();
      form.submit();
    }catch(e){
      guide.style.borderColor='#ef4444';
      status.textContent='Impossibile verificare il prodotto. Riprova.';
      submitted=false;
    }
  }"""

    if old_submit not in html:
        raise RuntimeError("Submit scanner originale non trovato")
    html=html.replace(old_submit,new_submit,1)

    # Testo guida più utile per QR piccoli.
    html=html.replace(
        "Fotocamera attiva. Inquadra il QR dentro il riquadro.",
        "Fotocamera attiva. Avvicina il QR finché è nitido."
    )
    replacements={
        "📷 Inquadra il badge":"📷 Scansiona il prodotto",
        "Inquadra il QR nel riquadro.":"Inquadra il QR applicato al gioiello.",
        'placeholder="Codice badge o lettore USB"':'placeholder="Codice prodotto o lettore USB"',
        "Badge letto. Accesso in corso…":"QR letto. Ricerca del prodotto…",
        "Questo browser non permette l’accesso alla fotocamera. Usa password o lettore USB.":"Questo browser non permette l’accesso alla fotocamera. Usa il codice prodotto o un lettore USB.",
        "Inquadra il QR oppure inserisci il codice del badge.":"Inquadra il QR oppure inserisci il codice del prodotto.",
        "Badge camera error":"Product QR camera error",
        "Fotocamera non avviata.":"Fotocamera pronta.",
    }
    for old,new in replacements.items():
        html=html.replace(old,new)

    return html

def create_badge_pdf(badge_name, token):
    """Crea un badge A6 verticale fronte/retro, pronto per stampa duplex."""
    qr_payload = BADGE_PREFIX + token
    output = BytesIO()

    page_w, page_h = 105 * mm, 148 * mm  # A6 verticale
    gold = colors.HexColor("#D8AE4D")
    gold_light = colors.HexColor("#F1D179")
    gold_dark = colors.HexColor("#7C5A19")
    black = colors.HexColor("#070707")
    black_2 = colors.HexColor("#141414")
    white = colors.HexColor("#F8F6F0")

    c = canvas.Canvas(output, pagesize=(page_w, page_h))
    c.setTitle(f"Badge A6 TBS ONE - {badge_name}")

    def draw_background():
        c.setFillColor(black)
        c.rect(0, 0, page_w, page_h, fill=1, stroke=0)

        c.setFillColor(black_2)
        c.rect(0, page_h * .72, page_w, page_h * .28, fill=1, stroke=0)

        c.saveState()
        c.setStrokeColor(colors.HexColor("#1D1D1D"))
        c.setLineWidth(.28)
        for i in range(-8, 18):
            offset = i * 10 * mm
            c.line(offset, 0, offset + 62 * mm, page_h)
        c.restoreState()

        c.setStrokeColor(gold_dark)
        c.setLineWidth(1.2)
        c.roundRect(5 * mm, 5 * mm, page_w - 10 * mm, page_h - 10 * mm,
                    5 * mm, fill=0, stroke=1)

        c.setStrokeColor(gold)
        c.setLineWidth(.45)
        c.roundRect(7 * mm, 7 * mm, page_w - 14 * mm, page_h - 14 * mm,
                    4 * mm, fill=0, stroke=1)

    def draw_logo(center_y, max_w=78 * mm, max_h=54 * mm):
        logo = jewelry_badge_logo_reader()
        if logo:
            c.drawImage(
                logo,
                (page_w - max_w) / 2,
                center_y - max_h / 2,
                width=max_w,
                height=max_h,
                preserveAspectRatio=True,
                mask="auto",
                anchor="c",
            )
        else:
            c.setFillColor(gold)
            c.setFont("Helvetica-Bold", 22)
            c.drawCentredString(page_w / 2, center_y, "JEWELRY")
            c.setFont("Helvetica", 10)
            c.drawCentredString(page_w / 2, center_y - 7 * mm, "atelier d'eccellenza")

    def draw_separator(y):
        c.setStrokeColor(gold)
        c.setLineWidth(.6)
        c.line(20 * mm, y, 46 * mm, y)
        c.line(59 * mm, y, 85 * mm, y)
        c.setFillColor(gold_light)
        c.circle(page_w / 2, y, 1.25 * mm, fill=1, stroke=0)

    # -------------------------- FRONTE --------------------------
    draw_background()
    draw_logo(page_h - 47 * mm, 82 * mm, 58 * mm)
    draw_separator(70 * mm)

    name = (badge_name or "").strip().upper()[:34]
    if len(name) <= 12:
        name_size = 28
    elif len(name) <= 20:
        name_size = 23
    else:
        name_size = 18

    c.setFillColor(white)
    c.setFont("Helvetica-Bold", name_size)
    c.drawCentredString(page_w / 2, 54 * mm, name)

    c.setFillColor(gold)
    c.setFont("Helvetica", 10)
    c.drawCentredString(page_w / 2, 43 * mm, "TATTOO BEAUTY SALOON")

    c.setStrokeColor(gold_dark)
    c.setLineWidth(.55)
    c.line(28 * mm, 35 * mm, page_w - 28 * mm, 35 * mm)

    c.setFillColor(gold_light)
    c.setFont("Helvetica-Bold", 13)
    c.drawCentredString(page_w / 2, 24 * mm, "TBS ONE")

    c.showPage()

    # --------------------------- RETRO --------------------------
    draw_background()
    draw_logo(page_h - 33 * mm, 59 * mm, 42 * mm)

    c.setFillColor(gold_light)
    c.setFont("Helvetica-Bold", 9.5)
    c.drawCentredString(page_w / 2, 96 * mm, "INQUADRA IL QR CODE")
    c.drawCentredString(page_w / 2, 90 * mm, "PER ACCEDERE AL GESTIONALE")

    qr_size = 52 * mm
    panel_size = 59 * mm
    panel_x = (page_w - panel_size) / 2
    panel_y = 25 * mm

    c.setFillColor(colors.white)
    c.roundRect(panel_x, panel_y, panel_size, panel_size, 5 * mm, fill=1, stroke=0)

    widget = qr.QrCodeWidget(qr_payload)
    bounds = widget.getBounds()
    scale = qr_size / max(bounds[2] - bounds[0], bounds[3] - bounds[1])
    drawing = Drawing(qr_size, qr_size, transform=[scale, 0, 0, scale, 0, 0])
    drawing.add(widget)
    renderPDF.draw(
        drawing,
        c,
        (page_w - qr_size) / 2,
        panel_y + (panel_size - qr_size) / 2,
    )

    c.setFillColor(gold)
    c.setFont("Helvetica-Bold", 7.5)
    c.drawCentredString(page_w / 2, 17 * mm, "USO PERSONALE E RISERVATO")

    c.setFillColor(colors.HexColor("#D8D2C7"))
    c.setFont("Helvetica", 7)
    c.drawCentredString(page_w / 2, 12 * mm, "Restituire in caso di smarrimento")

    c.showPage()
    c.save()
    output.seek(0)
    return output

def suspend_current_cart(db, reason="Blocco cassa"):
    raw=dict(session.get("cart",{}))
    if not raw: return None
    cur=db.execute("INSERT INTO suspended_carts(owner_user_id,owner_username,status,reason) VALUES(?,?,'Sospeso',?)",(session.get("user_id"),session.get("user","sconosciuto"),reason))
    cart_id=cur.lastrowid
    for key,value in raw.items():
        try: product_id=int(key); quantity=max(1,int(value))
        except (TypeError,ValueError): continue
        db.execute("INSERT OR REPLACE INTO suspended_cart_items(cart_id,product_id,quantity) VALUES(?,?,?)",(cart_id,product_id,quantity))
    return cart_id

def restore_suspended_cart(db, cart_id):
    cart=db.execute("SELECT * FROM suspended_carts WHERE id=? AND status='Sospeso'",(cart_id,)).fetchone()
    if not cart: return None
    rows=db.execute("SELECT product_id,quantity FROM suspended_cart_items WHERE cart_id=?",(cart_id,)).fetchall()
    restored={str(r["product_id"]):int(r["quantity"]) for r in rows}
    db.execute("UPDATE suspended_carts SET status='Ripreso',updated_at=CURRENT_TIMESTAMP,resumed_by_user_id=?,resumed_by_username=? WHERE id=?",(session.get("user_id"),session.get("user"),cart_id))
    return restored,cart

def photo_data(upload):
    if not upload or not upload.filename: return None
    raw=upload.read(); return f"data:{upload.mimetype or 'image/jpeg'};base64,{base64.b64encode(raw).decode()}" if raw else None

def values(form):
    brand=form["brand_code"].strip().upper()
    return (form["supplier_code"].strip().upper(),brand,int(form["quantity"]),float(form["price"].replace(",",".")),form.get("category") or infer_category(brand),form.get("material",""),form.get("color",""),form.get("size",""),form.get("stone",""),form.get("thread_type",""),form.get("notes",""),max(0,int(form.get("min_stock",1) or 1)),form.get("location","").strip(),float((form.get("cost_price","0") or "0").replace(",",".")),1 if form.get("is_new") else 0,1 if form.get("is_bestseller") else 0,form.get("model_name","").strip(),form.get("variant_group","").strip().upper())

def variant_conflict(db, product_id, variant_group, color, size, stone):
    """Restituisce una variante duplicata nello stesso gruppo, se presente."""
    group=(variant_group or "").strip().upper()
    if not group:
        return None
    return db.execute(
        """SELECT id, brand_code FROM products
           WHERE id<>? AND UPPER(COALESCE(variant_group,''))=?
             AND UPPER(TRIM(COALESCE(color,'')))=UPPER(TRIM(?))
             AND UPPER(TRIM(COALESCE(size,'')))=UPPER(TRIM(?))
             AND UPPER(TRIM(COALESCE(stone,'')))=UPPER(TRIM(?))
           LIMIT 1""",
        (product_id or 0, group, color or "", size or "", stone or "")
    ).fetchone()


def next_sale_number(db):
    prefix=now_rome().strftime("V%Y%m%d")
    row=db.execute("SELECT COUNT(DISTINCT sale_number) FROM sales WHERE sale_number LIKE ?",(prefix+"%",)).fetchone()
    return f"{prefix}-{(row[0] or 0)+1:03d}"


def next_treasury_number(db):
    prefix=now_rome().strftime("TS%Y%m%d")
    row=db.execute("SELECT COUNT(*) FROM treasury_movements WHERE movement_number LIKE ?",(prefix+"%",)).fetchone()
    return f"{prefix}-{(row[0] or 0)+1:04d}"

def utc_bounds_for_rome_day(day):
    start=datetime.combine(day,time.min,tzinfo=ROME_TZ)
    end=start+timedelta(days=1)
    fmt="%Y-%m-%d %H:%M:%S"
    return start.astimezone(timezone.utc).strftime(fmt),end.astimezone(timezone.utc).strftime(fmt)

def sales_totals_for_period(db,start_utc,end_utc):
    return db.execute("""SELECT COALESCE(SUM(quantity*unit_price),0) total,
      COALESCE(SUM(CASE WHEN payment_method='Contanti' THEN quantity*unit_price ELSE 0 END),0) cash,
      COALESCE(SUM(CASE WHEN payment_method IN ('POS','Bancomat') THEN quantity*unit_price ELSE 0 END),0) card
      FROM sales WHERE status='Confermata' AND created_at>=? AND created_at<?""",(start_utc,end_utc)).fetchone()

def treasury_cash_balance(db,until_utc=None):
    sw=" AND created_at<?" if until_utc else ""; mw=" WHERE created_at<?" if until_utc else ""; args=(until_utc,) if until_utc else ()
    cash=db.execute("SELECT COALESCE(SUM(quantity*unit_price),0) FROM sales WHERE status='Confermata' AND payment_method='Contanti'"+sw,args).fetchone()[0]
    rows=db.execute("SELECT movement_type,COALESCE(SUM(amount),0) amount FROM treasury_movements"+mw+" GROUP BY movement_type",args).fetchall()
    t={r['movement_type']:float(r['amount'] or 0) for r in rows}
    return float(cash or 0)+t.get('return',0)+t.get('deposit',0)-t.get('withdrawal',0)

def treasury_open_debts(db,until_utc=None):
    where="WHERE COALESCE(responsible_username,'')<>''"
    params=()
    if until_utc:
        where+=" AND created_at<?"; params=(until_utc,)
    return db.execute("""SELECT responsible_username,
      COALESCE(SUM(CASE WHEN movement_type='withdrawal' AND refundable=1 THEN amount WHEN movement_type='return' THEN -amount ELSE 0 END),0) amount
      FROM treasury_movements """+where+""" GROUP BY responsible_username
      HAVING amount>0.005 ORDER BY amount DESC""",params).fetchall()

def create_daily_closure(db,day):
    start,end=utc_bounds_for_rome_day(day); sales=sales_totals_for_period(db,start,end)
    moves=db.execute("""SELECT COALESCE(SUM(CASE WHEN movement_type='withdrawal' AND refundable=0 THEN amount ELSE 0 END),0) definitive,
      COALESCE(SUM(CASE WHEN movement_type='withdrawal' AND refundable=1 THEN amount ELSE 0 END),0) refundable,
      COALESCE(SUM(CASE WHEN movement_type='return' THEN amount ELSE 0 END),0) returned
      FROM treasury_movements WHERE created_at>=? AND created_at<?""",(start,end)).fetchone()
    cash=treasury_cash_balance(db,end); debts=sum(float(x['amount']) for x in treasury_open_debts(db,end))
    db.execute("""INSERT OR IGNORE INTO treasury_daily_closures
      (closure_date,sales_total,cash_sales,card_sales,definitive_outflows,refundable_withdrawals,returns_total,theoretical_cash,open_debts)
      VALUES(?,?,?,?,?,?,?,?,?)""",(day.isoformat(),sales['total'],sales['cash'],sales['card'],moves['definitive'],moves['refundable'],moves['returned'],cash,debts))

def ensure_daily_closures():
    yesterday=now_rome().date()-timedelta(days=1)
    with connect() as db:
        last=db.execute("SELECT MAX(closure_date) FROM treasury_daily_closures").fetchone()[0]
        current=date.fromisoformat(last)+timedelta(days=1) if last else yesterday
        while current<=yesterday:
            create_daily_closure(db,current); current+=timedelta(days=1)
        db.commit()

def add_reorder_quantity(db, product_id, quantity):
    db.execute("INSERT INTO reorder_pending(product_id,quantity) VALUES(?,?) ON CONFLICT(product_id) DO UPDATE SET quantity=quantity+excluded.quantity",(product_id,quantity))

