@app.post("/boutique/carrello/aggiorna/<int:product_id>")
def client_update_cart(product_id):
    try: qty=max(1,int(request.form.get("quantity",1)))
    except ValueError: qty=1
    with connect() as db: p=db.execute("SELECT quantity FROM products WHERE id=?",(product_id,)).fetchone()
    if not p or p["quantity"]<1:
        cart=dict(session.get("client_cart",{})); cart.pop(str(product_id),None)
    else:
        cart=dict(session.get("client_cart",{})); cart[str(product_id)]=min(qty,p["quantity"])
    session["client_cart"]=cart; session.modified=True
    return redirect(url_for("client_cart"))

