@app.post("/customer-orders/<int:order_id>/confirm")
@role_required("admin","manager")
def confirm_customer_order(order_id):
    with connect() as db:
        order=db.execute("SELECT * FROM customer_orders WHERE id=?",(order_id,)).fetchone()
        if not order or order["status"]!="Nuovo": flash("Ordine non disponibile per la conferma."); return redirect(url_for("customer_orders"))
        items=db.execute("SELECT * FROM customer_order_items WHERE order_id=?",(order_id,)).fetchall()
        for item in items:
            p=db.execute("SELECT * FROM products WHERE id=?",(item["product_id"],)).fetchone()
            if not p or p["quantity"]<item["quantity"]:
                flash(f"Disponibilità insufficiente per {item['product_code']}. Ordine non confermato.")
                return redirect(url_for("customer_orders"))
        sale_number=next_sale_number(db)
        for item in items:
            p=db.execute("SELECT * FROM products WHERE id=?",(item["product_id"],)).fetchone()
            db.execute("UPDATE products SET quantity=quantity-? WHERE id=?",(item["quantity"],item["product_id"]))
            db.execute("""INSERT INTO sales(user_id,username,product_id,product_code,quantity,unit_price,sale_number,payment_method,channel,status) VALUES(?,?,?,?,?,?,?,?,?,'Confermata')""",(session.get("user_id"),session.get("user","sconosciuto"),item["product_id"],item["product_code"],item["quantity"],item["unit_price"],sale_number,"Da concordare","Online"))
            add_reorder_quantity(db,item["product_id"],item["quantity"])
        db.execute("UPDATE customer_orders SET status='Confermato' WHERE id=?",(order_id,))
        log_action(db,"Ordine cliente confermato",details=f"{order['order_number']}; vendita {sale_number}")
        db.commit()
    flash("Ordine confermato e magazzino aggiornato.")
    return redirect(url_for("customer_orders"))

@app.post("/customer-orders/<int:order_id>/cancel")
@role_required("admin","manager")
def cancel_customer_order(order_id):
    with connect() as db:
        order=db.execute("SELECT * FROM customer_orders WHERE id=?",(order_id,)).fetchone()
        if order and order["status"]=="Nuovo":
            db.execute("UPDATE customer_orders SET status='Annullato' WHERE id=?",(order_id,)); log_action(db,"Ordine cliente annullato",details=order["order_number"]); db.commit()
            flash("Richiesta annullata.")
    return redirect(url_for("customer_orders"))

@app.route("/account/password",methods=["GET","POST"])
@login_required
def change_password():
    if request.method=="POST":
        current=request.form.get("current_password",""); new=request.form.get("new_password",""); confirm=request.form.get("confirm_password","")
        if len(new)<8: flash("La nuova password deve avere almeno 8 caratteri.")
        elif new!=confirm: flash("Le due nuove password non coincidono.")
        else:
            with connect() as db:
                user=db.execute("SELECT * FROM users WHERE id=?",(session.get("user_id"),)).fetchone()
                if not user or not check_password_hash(user["password_hash"],current): flash("La password attuale non è corretta.")
                else:
                    db.execute("UPDATE users SET password_hash=? WHERE id=?",(generate_password_hash(new),user["id"])); log_action(db,"Password personale modificata"); db.commit()
                    flash("Password modificata correttamente."); return redirect(url_for("home"))
    return page("Cambia password",'''<h1>Cambia password</h1><div class="card" style="max-width:560px"><form method="post"><p><label>Password attuale<input name="current_password" type="password" required></label></p><p><label>Nuova password<input name="new_password" type="password" minlength="8" required></label></p><p><label>Conferma nuova password<input name="confirm_password" type="password" minlength="8" required></label></p><button>Aggiorna password</button></form></div>''')

@app.get("/treasury")
@role_required("admin","manager")
def treasury():
    today=now_rome().date(); start,end=utc_bounds_for_rome_day(today); month_start,_=utc_bounds_for_rome_day(today.replace(day=1))
    with connect() as db:
        day_sales=sales_totals_for_period(db,start,end); month_sales=sales_totals_for_period(db,month_start,end)
        cash=treasury_cash_balance(db); debts=treasury_open_debts(db); debt_total=sum(float(x['amount']) for x in debts)
        outflows=db.execute("SELECT COALESCE(SUM(amount),0) FROM treasury_movements WHERE movement_type='withdrawal' AND refundable=0").fetchone()[0]
        recent=db.execute("SELECT * FROM treasury_movements ORDER BY id DESC LIMIT 40").fetchall(); count=db.execute("SELECT * FROM treasury_cash_counts ORDER BY id DESC LIMIT 1").fetchone(); closures=db.execute("SELECT * FROM treasury_daily_closures ORDER BY closure_date DESC LIMIT 14").fetchall()
    return page("Tesoreria",'''<style>.money{font-size:30px;font-weight:800}.buttons{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.debt{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #eee}.plus{color:#047857}.minus{color:#b91c1c}</style><h1>💎 Tesoreria Gioielli</h1><div class="grid"><div class="card"><div class="muted">Incasso oggi</div><div class="money">€ {{'%.2f'|format(day_sales.total)}}</div><p>💵 € {{'%.2f'|format(day_sales.cash)}} · 💳 € {{'%.2f'|format(day_sales.card)}}</p></div><div class="card"><div class="muted">Incasso mese</div><div class="money">€ {{'%.2f'|format(month_sales.total)}}</div><p>Contanti € {{'%.2f'|format(month_sales.cash)}} · Bancomat € {{'%.2f'|format(month_sales.card)}}</p></div><div class="card"><div class="muted">Contanti nel cassetto</div><div class="money">€ {{'%.2f'|format(cash)}}</div></div><div class="card"><div class="muted">Da restituire</div><div class="money">€ {{'%.2f'|format(debt_total)}}</div><p>Uscite definitive € {{'%.2f'|format(outflows)}}</p></div></div><div class="card buttons"><a class="danger" href="{{url_for('treasury_withdrawal')}}" style="padding:13px;text-align:center;text-decoration:none;border-radius:9px">➖ Prelievo</a><a class="success" href="{{url_for('treasury_return')}}" style="padding:13px;text-align:center;text-decoration:none;border-radius:9px">➕ Restituzione</a><a class="view" href="{{url_for('treasury_count')}}" style="padding:13px;text-align:center;text-decoration:none;border-radius:9px">🧮 Conta cassetto</a><form method="post" action="{{url_for('treasury_empty')}}" onsubmit="return confirm('Confermi lo svuotamento completo del cassetto? Il movimento resterà nello storico.')"><button class="danger" style="width:100%;height:100%">Svuota cassetto</button></form></div><div class="grid"><div class="card"><h2>Chi deve rimettere denaro</h2>{% for d in debts %}<div class="debt"><b>{{d.responsible_username}}</b><b class="minus">€ {{'%.2f'|format(d.amount)}}</b></div>{% else %}<p class="muted">Nessun importo aperto.</p>{% endfor %}</div><div class="card"><h2>Ultimo conteggio</h2>{% if count %}<p>{{count.created_at|rome_time}} · {{count.username}}</p><p>Teorico € {{'%.2f'|format(count.theoretical_amount)}}<br>Contati € {{'%.2f'|format(count.counted_amount)}}<br>Differenza <b>€ {{'%.2f'|format(count.difference)}}</b></p>{% else %}<p class="muted">Nessun conteggio.</p>{% endif %}</div></div><div class="card"><h2>Ultimi movimenti</h2>{% for x in recent %}<p><b>{{x.movement_number}}</b> · {{x.created_at|rome_time}} · {{x.actor_username}}<br>{{x.category}}{% if x.responsible_username %} · Prelevato/restituito da <b>{{x.responsible_username}}</b>{% endif %}{% if x.supplier %} · Fornitore {{x.supplier}}{% endif %}<br><b class="{{'plus' if x.movement_type=='return' else 'minus'}}">{{'+' if x.movement_type=='return' else '-'}} € {{'%.2f'|format(x.amount)}}</b>{% if x.notes %}<br><span class="muted">{{x.notes}}</span>{% endif %}</p><hr>{% else %}<p class="muted">Nessun movimento.</p>{% endfor %}</div><div class="card"><h2>Chiusure giornaliere automatiche</h2><p class="muted">Create dopo mezzanotte; eventuali chiusure mancanti vengono recuperate alla prima apertura.</p>{% for c in closures %}<p><b>{{c.closure_date}}</b> · Totale € {{'%.2f'|format(c.sales_total)}} · Contanti € {{'%.2f'|format(c.cash_sales)}} · Bancomat € {{'%.2f'|format(c.card_sales)}}<br>Cassetto € {{'%.2f'|format(c.theoretical_cash)}} · Da restituire € {{'%.2f'|format(c.open_debts)}}</p><hr>{% else %}<p class="muted">La prima chiusura comparirà dopo mezzanotte.</p>{% endfor %}</div>''',day_sales=day_sales,month_sales=month_sales,cash=cash,debts=debts,debt_total=debt_total,outflows=outflows,recent=recent,count=count,closures=closures)

@app.post("/treasury/empty")
@role_required("admin","manager")
def treasury_empty():
    with connect() as db:
        amount=round(float(treasury_cash_balance(db) or 0),2)
        if amount<=0:
            flash("Il cassetto è già a zero.")
        else:
            number=next_treasury_number(db)
            db.execute("INSERT INTO treasury_movements(movement_number,movement_type,category,amount,actor_user_id,actor_username,responsible_username,notes,refundable) VALUES(?,?,?,?,?,?,?,?,0)",(number,"withdrawal","Svuotamento cassetto",amount,session.get("user_id"),session.get("user","sconosciuto"),session.get("user","sconosciuto"),"Azzeramento cassetto con storico"))
            log_action(db,"Cassetto svuotato",details=f"{number}; € {amount:.2f}")
            db.commit(); flash(f"Cassetto azzerato. Registrato prelievo di € {amount:.2f}.")
    return redirect(url_for("treasury"))

@app.route("/treasury/withdrawal",methods=["GET","POST"])
@role_required("admin","manager")
def treasury_withdrawal():
    with connect() as db:
        people=db.execute("SELECT username,role FROM users WHERE active=1 AND role IN ('admin','manager') ORDER BY username").fetchall()
        if request.method=="POST":
            try: amount=float(request.form.get("amount","0").replace(",","."))
            except ValueError: amount=0
            category=request.form.get("category",""); responsible=request.form.get("responsible_username",session.get("user")); refundable=1 if category=="Prestito / Anticipo" else 0
            allowed={"Acquisto fornitura","Acquisto materiale","Versamento banca","Spese negozio","Prestito / Anticipo","Altro"}
            if amount<=0 or category not in allowed: flash("Inserisci importo e causale validi.")
            elif amount>treasury_cash_balance(db)+0.005: flash("Il prelievo supera il contante disponibile.")
            elif responsible not in {x['username'] for x in people}: flash("Seleziona Admin o Gestore.")
            else:
                number=next_treasury_number(db); db.execute("""INSERT INTO treasury_movements(movement_number,movement_type,category,amount,actor_user_id,actor_username,responsible_username,supplier,invoice_number,notes,refundable) VALUES(?,?,?,?,?,?,?,?,?,?,?)""",(number,"withdrawal",category,amount,session.get("user_id"),session.get("user"),responsible,request.form.get("supplier","").strip(),request.form.get("invoice_number","").strip(),request.form.get("notes","").strip(),refundable)); log_action(db,"Prelievo tesoreria",details=f"{number}; {category}; € {amount:.2f}; {responsible}"); db.commit(); flash("Prelievo registrato."); return redirect(url_for("treasury"))
    return page("Prelievo",'''<h1>Nuovo prelievo</h1><div class="card"><form method="post"><p><label>Importo<input name="amount" inputmode="decimal" required></label></p><p><label>Causale<select name="category" id="cat" required><option value="">Seleziona</option><option>Acquisto fornitura</option><option>Acquisto materiale</option><option>Versamento banca</option><option>Spese negozio</option><option>Prestito / Anticipo</option><option>Altro</option></select></label></p><p><label>Chi ha prelevato<select name="responsible_username">{% for p in people %}<option value="{{p.username}}">{{p.username}} · {{roles.get(p.role,p.role)}}</option>{% endfor %}</select></label></p><div id="supplier"><p><label>Fornitore<input name="supplier"></label></p><p><label>Fattura/riferimento<input name="invoice_number"></label></p></div><p><label>Note<textarea name="notes"></textarea></label></p><button>Registra</button></form><p class="muted">Solo Prestito / Anticipo crea un importo da restituire. Le altre causali sono uscite definitive.</p></div><script>const c=document.getElementById('cat'),s=document.getElementById('supplier');function u(){s.style.display=c.value==='Acquisto fornitura'?'block':'none'}c.onchange=u;u()</script>''',people=people,roles=ROLE_LABELS)

@app.route("/treasury/return",methods=["GET","POST"])
@role_required("admin","manager")
def treasury_return():
    with connect() as db:
        debts=treasury_open_debts(db)
        if request.method=="POST":
            who=request.form.get("responsible_username",""); debt=next((float(x['amount']) for x in debts if x['responsible_username']==who),0)
            try: amount=float(request.form.get("amount","0").replace(",","."))
            except ValueError: amount=0
            if amount<=0 or amount>debt+0.005: flash("Importo non valido o superiore al debito.")
            else:
                number=next_treasury_number(db); db.execute("INSERT INTO treasury_movements(movement_number,movement_type,category,amount,actor_user_id,actor_username,responsible_username,notes) VALUES(?,?,?,?,?,?,?,?)",(number,"return","Restituzione",amount,session.get("user_id"),session.get("user"),who,request.form.get("notes","").strip())); log_action(db,"Restituzione tesoreria",details=f"{number}; {who}; € {amount:.2f}"); db.commit(); flash("Restituzione registrata."); return redirect(url_for("treasury"))
    return page("Restituzione",'''<h1>Restituzione</h1><div class="card">{% if debts %}<form method="post"><p><label>Chi restituisce<select name="responsible_username">{% for d in debts %}<option value="{{d.responsible_username}}">{{d.responsible_username}} · € {{'%.2f'|format(d.amount)}}</option>{% endfor %}</select></label></p><p><label>Importo<input name="amount" inputmode="decimal" required></label></p><p><label>Note<textarea name="notes"></textarea></label></p><button>Registra</button></form>{% else %}<p>Nessun importo da restituire.</p>{% endif %}</div>''',debts=debts)

@app.route("/treasury/count",methods=["GET","POST"])
@role_required("admin","manager")
def treasury_count():
    with connect() as db:
        theoretical=treasury_cash_balance(db)
        if request.method=="POST":
            try: counted=float(request.form.get("counted_amount","0").replace(",","."))
            except ValueError: counted=-1
            if counted<0: flash("Importo non valido.")
            else:
                diff=counted-theoretical; db.execute("INSERT INTO treasury_cash_counts(counted_amount,theoretical_amount,difference,username,notes) VALUES(?,?,?,?,?)",(counted,theoretical,diff,session.get("user"),request.form.get("notes","").strip())); log_action(db,"Conteggio cassetto",details=f"Teorico € {theoretical:.2f}; contato € {counted:.2f}; differenza € {diff:.2f}"); db.commit(); flash("Conteggio registrato."); return redirect(url_for("treasury"))
    return page("Conta cassetto",'''<h1>Conta il cassetto</h1><div class="card"><p>Saldo teorico: <b class="metric">€ {{'%.2f'|format(theoretical)}}</b></p><form method="post"><p><label>Contanti realmente presenti<input name="counted_amount" inputmode="decimal" required></label></p><p><label>Note<textarea name="notes"></textarea></label></p><button>Registra conteggio</button></form><p class="muted">Il conteggio non modifica il saldo teorico.</p></div>''',theoretical=theoretical)

@app.get("/health")
def health():
    """Diagnostica essenziale del servizio e del database, senza dati sensibili."""
    db_exists=os.path.exists(DB_PATH)
    db_size=os.path.getsize(DB_PATH) if db_exists else 0
    try:
        with connect() as db:
            user_count=db.execute("SELECT COUNT(*) FROM users").fetchone()[0]
            active_admins=db.execute(
                "SELECT COUNT(*) FROM users WHERE active=1 AND role IN ('admin','manager')"
            ).fetchone()[0]
        db_ok=True
        db_error=None
    except Exception as exc:
        db_ok=False
        db_error=str(exc)
        user_count=None
        active_admins=None

    return {
        "status":"ok" if db_ok else "error",
        "version":APP_VERSION,
        "database_path":DB_PATH,
        "database_exists":db_exists,
        "database_size_bytes":db_size,
        "persistent":not DB_IS_EPHEMERAL,
        "users":user_count,
        "active_admins_or_managers":active_admins,
        "database_error":db_error,
    }, (200 if db_ok else 500)


def _ensure_notifications(db):
    db.execute("""CREATE TABLE IF NOT EXISTS notifications(
        id INTEGER PRIMARY KEY,
        recipient_user_id INTEGER NOT NULL,
        recipient_username TEXT,
        notification_type TEXT NOT NULL,
        title TEXT NOT NULL,
        message TEXT,
        reference_type TEXT,
        reference_id INTEGER,
        created_at TEXT DEFAULT CURRENT_TIMESTAMP,
        read_at TEXT,
        archived_at TEXT,
        archived_by_user_id INTEGER,
        archived_by_username TEXT,
        event_key TEXT
    )""")
    ensure_column(db,"notifications","recipient_username","TEXT")
    ensure_column(db,"notifications","event_key","TEXT")
    db.execute("CREATE INDEX IF NOT EXISTS idx_notifications_recipient ON notifications(recipient_user_id,archived_at,read_at,created_at)")
    db.execute("CREATE INDEX IF NOT EXISTS idx_notifications_username ON notifications(recipient_username,archived_at,read_at,created_at)")
    db.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_notifications_event_user ON notifications(recipient_user_id,event_key) WHERE event_key IS NOT NULL")


def _current_user_for_identity(db, user_id=None, username=None):
    """Risolve l'account attivo corrente anche se un utente è stato ricreato con un nuovo ID."""
    row=None
    if user_id:
        row=db.execute("SELECT id,username FROM users WHERE id=? AND active=1",(user_id,)).fetchone()
    if not row and username:
        row=db.execute("SELECT id,username FROM users WHERE lower(username)=lower(?) AND active=1 ORDER BY id DESC LIMIT 1",(username,)).fetchone()
    return row


def _notify_user(db,user_id,kind,title,message,reference_type=None,reference_id=None,event_key=None,recipient_username=None):
    _ensure_notifications(db)
    recipient=_current_user_for_identity(db,user_id,recipient_username)
    if not recipient:
        return False
    db.execute("""INSERT OR IGNORE INTO notifications(
        recipient_user_id,recipient_username,notification_type,title,message,
        reference_type,reference_id,event_key
    ) VALUES(?,?,?,?,?,?,?,?)""",(
        recipient['id'],recipient['username'],kind,title,message,
        reference_type,reference_id,event_key
    ))
    return True


def _notify_roles(db,roles,kind,title,message,reference_type=None,reference_id=None,event_key=None):
    placeholders=','.join('?' for _ in roles)
    users=db.execute(f"SELECT id,username FROM users WHERE active=1 AND role IN ({placeholders})",tuple(roles)).fetchall()
    for user in users:
        user_event_key=f"{event_key}:user:{user['id']}" if event_key else None
        _notify_user(db,user['id'],kind,title,message,reference_type,reference_id,user_event_key,user['username'])


def _repair_notification_recipients(db):
    """Ricollega notifiche e richieste agli account attivi quando gli utenti sono stati ricreati."""
    _ensure_notifications(db)
    # Completa username mancanti per notifiche ancora legate a un account esistente.
    db.execute("""UPDATE notifications
                  SET recipient_username=(SELECT username FROM users WHERE users.id=notifications.recipient_user_id)
                  WHERE recipient_username IS NULL
                    AND EXISTS(SELECT 1 FROM users WHERE users.id=notifications.recipient_user_id)""")
    # Se lo stesso username ora ha un nuovo ID, sposta la notifica sul profilo attivo corrente.
    rows=db.execute("SELECT id,recipient_user_id,recipient_username FROM notifications WHERE recipient_username IS NOT NULL").fetchall()
    for n in rows:
        current=_current_user_for_identity(db,None,n['recipient_username'])
        if current and current['id'] != n['recipient_user_id']:
            try:
                db.execute("UPDATE notifications SET recipient_user_id=? WHERE id=?",(current['id'],n['id']))
            except sqlite3.IntegrityError:
                # Una notifica equivalente esiste già sul nuovo profilo.
                db.execute("DELETE FROM notifications WHERE id=?",(n['id'],))


def _backfill_personal_notifications(db):
    """Crea/ripara gli esiti sconto personali, anche dopo ricreazione degli utenti."""
    _ensure_notifications(db)
    _repair_notification_recipients(db)
    rows=db.execute("""SELECT id,requester_user_id,requester_username,product_code,original_price,requested_price,status,approver_username
                       FROM discount_requests
                       WHERE status IN ('Approvata','Applicata','Rifiutata')""").fetchall()
    for req in rows:
        recipient=_current_user_for_identity(db,req['requester_user_id'],req['requester_username'])
        if not recipient:
            continue
        approved=req['status'] in ('Approvata','Applicata')
        kind='discount_approved' if approved else 'discount_rejected'
        title='Sconto autorizzato' if approved else 'Sconto rifiutato'
        message=f"{req['product_code']} · € {float(req['original_price']):.2f} → € {float(req['requested_price']):.2f}"
        if req['approver_username']:
            message += f" · {req['approver_username']}"
        _notify_user(db,recipient['id'],kind,title,message,'discount',req['id'],f"discount:{req['id']}:{kind}",recipient['username'])


def _backfill_operational_notifications(db):
    """Garantisce copie indipendenti per Admin/Gestore e conserva gli eventi conclusi nello storico."""
    _ensure_notifications(db)
    _repair_notification_recipients(db)
    staff=db.execute("SELECT id,username FROM users WHERE active=1 AND role IN ('admin','manager')").fetchall()
    requests=db.execute("""SELECT id,requester_username,product_code,original_price,requested_price,
                                  status,created_at,decided_at,approver_user_id,approver_username
                           FROM discount_requests""").fetchall()
    for req in requests:
        message=f"{req['requester_username']} · {req['product_code']} · € {float(req['original_price']):.2f} → € {float(req['requested_price']):.2f}"
        for user in staff:
            event_key=f"discount:{req['id']}:request:user:{user['id']}"
            _notify_user(db,user['id'],'discount_request','Nuova richiesta sconto',message,
                         'discount',req['id'],event_key,user['username'])
            if req['status'] != 'In attesa':
                db.execute("""UPDATE notifications
                              SET read_at=COALESCE(read_at,COALESCE(?,CURRENT_TIMESTAMP)),
                                  archived_at=COALESCE(archived_at,COALESCE(?,CURRENT_TIMESTAMP)),
                                  archived_by_user_id=COALESCE(archived_by_user_id,?),
                                  archived_by_username=COALESCE(archived_by_username,?)
                              WHERE recipient_user_id=? AND event_key=?""",
                           (req['decided_at'],req['decided_at'],req['approver_user_id'],
                            req['approver_username'] or 'Sistema',user['id'],event_key))
    sales=db.execute("""SELECT MIN(id) AS first_id,sale_number,username,payment_method,created_at,
                               SUM(quantity) AS pieces,SUM(quantity*unit_price) AS total
                        FROM sales WHERE status='Confermata'
                        GROUP BY COALESCE(sale_number,'ID-' || id)
                        ORDER BY first_id""").fetchall()
    for sale in sales:
        message=f"{sale['username']} · {int(sale['pieces'] or 0)} articoli · € {float(sale['total'] or 0):.2f} · {sale['payment_method'] or 'Altro'}"
        for user in staff:
            event_key=f"sale:{sale['first_id']}:user:{user['id']}"
            _notify_user(db,user['id'],'sale','Nuova vendita',message,'sale',sale['first_id'],event_key,user['username'])


def _sync_all_notifications(db):
    _backfill_personal_notifications(db)
    _backfill_operational_notifications(db)


def _notification_unread_count(db,user_id):
    _ensure_notifications(db)
    _repair_notification_recipients(db)
    return int(db.execute("SELECT COUNT(*) FROM notifications WHERE recipient_user_id=? AND read_at IS NULL AND archived_at IS NULL",(user_id,)).fetchone()[0] or 0)

@app.get("/notifications/count")
@login_required
def notification_count():
    with connect() as db:
        _sync_all_notifications(db)
        db.commit()
        count=_notification_unread_count(db,session.get("user_id"))
    return jsonify({"count":count})

@app.get("/notifications")
@login_required
def notification_center():
    view=request.args.get('view','unread')
    if request.args.get('history')=='1': view='archive'
    if view not in ('unread','read','archive'): view='unread'
    with connect() as db:
        _sync_all_notifications(db)
        db.commit()
        if view=='archive':
            raw_rows=db.execute("SELECT * FROM notifications WHERE recipient_user_id=? AND archived_at IS NOT NULL ORDER BY archived_at DESC,id DESC LIMIT 200",(session.get('user_id'),)).fetchall()
        elif view=='read':
            raw_rows=db.execute("SELECT * FROM notifications WHERE recipient_user_id=? AND archived_at IS NULL AND read_at IS NOT NULL ORDER BY read_at DESC,id DESC LIMIT 150",(session.get('user_id'),)).fetchall()
        else:
            raw_rows=db.execute("SELECT * FROM notifications WHERE recipient_user_id=? AND archived_at IS NULL AND read_at IS NULL ORDER BY created_at DESC,id DESC LIMIT 150",(session.get('user_id'),)).fetchall()
        counts={
            'unread':db.execute("SELECT COUNT(*) FROM notifications WHERE recipient_user_id=? AND archived_at IS NULL AND read_at IS NULL",(session.get('user_id'),)).fetchone()[0],
            'read':db.execute("SELECT COUNT(*) FROM notifications WHERE recipient_user_id=? AND archived_at IS NULL AND read_at IS NOT NULL",(session.get('user_id'),)).fetchone()[0],
            'archive':db.execute("SELECT COUNT(*) FROM notifications WHERE recipient_user_id=? AND archived_at IS NOT NULL",(session.get('user_id'),)).fetchone()[0],
        }

    # Raggruppa solo le vendite consecutive dello stesso venditore nello stesso minuto.
    # Gli altri eventi rimangono singoli per conservare un flusso operativo chiaro.
    grouped=[]
    sale_groups={}
    for row in raw_rows:
        item=dict(row)
        if item.get('notification_type')=='sale':
            seller=(item.get('message') or '').split(' · ',1)[0].strip() or 'Venditore'
            minute=(item.get('created_at') or '')[:16]
            key=(seller,minute)
            if key not in sale_groups:
                sale_groups[key]={
                    'is_group':True,'seller':seller,'minute':minute,'items':[],
                    'created_at':item.get('created_at'),'read_at':item.get('read_at'),
                    'archived_at':item.get('archived_at'),'archived_by_username':item.get('archived_by_username')
                }
                grouped.append(sale_groups[key])
            sale_groups[key]['items'].append(item)
            try:
                parts=(item.get('message') or '').split(' · ')
                amount=float(parts[2].replace('€','').replace(',','.').strip()) if len(parts)>2 else 0.0
            except (ValueError,TypeError):
                amount=0.0
            sale_groups[key]['group_total']=sale_groups[key].get('group_total',0.0)+amount
            if not item.get('read_at'): sale_groups[key]['read_at']=None
        else:
            item['is_group']=False
            grouped.append(item)

    # I gruppi con una sola vendita vengono mostrati come notifica normale.
    rows=[]
    for item in grouped:
        if item.get('is_group') and len(item['items'])==1:
            single=item['items'][0]
            single['is_group']=False
            rows.append(single)
        else:
            rows.append(item)

    body="""<style>
    .notice-tabs{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:15px 0}.notice-tabs a{padding:14px 8px;border-radius:14px;background:#e5e7eb;color:#111;text-align:center;text-decoration:none;font-weight:950}.notice-tabs a.active{background:#111827;color:#fff}
    .notice-list{display:grid;gap:12px;margin-top:16px}.notice-row{display:grid;grid-template-columns:48px 1fr auto;gap:10px;align-items:center;background:#fff;border:1px solid #ddd;border-radius:16px;padding:14px;cursor:pointer;transition:transform .12s,box-shadow .12s}.notice-row:active{transform:scale(.99)}.notice-row:hover{box-shadow:0 8px 22px rgba(15,23,42,.08)}.notice-row.unread{border-left:7px solid #dc2626}.notice-row.read{border-left:7px solid #10b981}
    .notice-main{text-decoration:none;color:inherit}.trash{background:#fff0f0;color:#b91c1c;padding:10px;border-radius:12px}.status-pill{border-radius:99px;padding:3px 8px;font-size:11px;color:#fff;white-space:nowrap}.status-new{background:#dc2626}.status-read{background:#059669}.group-pill{background:#d7a72c;color:#111;border-radius:99px;padding:3px 8px;font-size:11px;font-weight:900}
    @media(max-width:560px){.notice-tabs{grid-template-columns:1fr}.notice-row{grid-template-columns:38px 1fr auto;padding:13px 10px}}
    </style>
    <h1>🔔 Centro notifiche</h1>
    <div class='notice-tabs'><a class='{% if view=="unread" %}active{% endif %}' href='{{url_for("notification_center",view="unread")}}'>🔴 Da leggere ({{counts.unread}})</a><a class='{% if view=="read" %}active{% endif %}' href='{{url_for("notification_center",view="read")}}'>🟢 Lette ({{counts.read}})</a><a class='{% if view=="archive" %}active{% endif %}' href='{{url_for("notification_center",view="archive")}}'>📚 Archivio ({{counts.archive}})</a></div>
    <p class='muted'>{% if view=='archive' %}Eventi archiviati: nessuna traccia viene eliminata.{% elif view=='read' %}Notifiche aperte ma non ancora archiviate.{% else %}Tocca qualsiasi punto della scheda per vedere il dettaglio.{% endif %}</p>
    <div class='notice-list'>{% for n in rows %}
      {% if n.is_group %}
      <div class='notice-row {% if not n.read_at and view!="archive" %}unread{% elif view!="archive" %}read{% endif %}' data-href='{{url_for("notification_sales_group",seller=n.seller,minute=n.minute)}}'>
        <div style='font-size:28px'>💰</div>
        <div class='notice-main'><b>{{n.seller}} · {{n.items|length}} vendite</b> <span class='group-pill'>RAGGRUPPATE</span>{% if not n.read_at and view!='archive' %} <span class='status-pill status-new'>NUOVE</span>{% elif view!='archive' %} <span class='status-pill status-read'>LETTE</span>{% endif %}<br>Totale gruppo: <b>€ {{'%.2f'|format(n.group_total)}}</b><br><small>{{n.created_at|rome_time}}{% if view=='archive' %} · archiviate {{n.archived_at|rome_time}} da {{n.archived_by_username or 'Sistema'}}{% endif %}</small></div>
        {% if view!='archive' %}<form method='post' action='{{url_for("archive_notification_group")}}' onsubmit="event.stopPropagation();return confirm('Archiviare tutte le notifiche di questo gruppo? Rimarranno nello storico.')"><input type='hidden' name='seller' value='{{n.seller}}'><input type='hidden' name='minute' value='{{n.minute}}'><button class='trash' type='submit'>🗑️</button></form>{% endif %}
      </div>
      {% else %}
      <div class='notice-row {% if not n.read_at and view!="archive" %}unread{% elif view!="archive" %}read{% endif %}' data-href='{{url_for("notification_detail",notification_id=n.id)}}'>
        <div style='font-size:28px'>{% if n.notification_type=='sale' %}💰{% elif n.notification_type=='discount_request' %}🏷️{% elif n.notification_type=='discount_approved' %}✅{% elif n.notification_type=='discount_rejected' %}❌{% else %}🔔{% endif %}</div>
        <div class='notice-main'><b>{{n.title}}</b>{% if not n.read_at and view!='archive' %} <span class='status-pill status-new'>NUOVA</span>{% elif view!='archive' %} <span class='status-pill status-read'>LETTA</span>{% endif %}<br>{{n.message or ''}}<br><small>{{n.created_at|rome_time}}{% if view=='archive' %} · archiviata {{n.archived_at|rome_time}} da {{n.archived_by_username or 'Sistema'}}{% endif %}</small></div>
        {% if view!='archive' %}<form method='post' action='{{url_for("archive_notification",notification_id=n.id)}}' onsubmit="event.stopPropagation();return confirm('Archiviare questa notifica? Rimarrà nello storico.')"><button class='trash' type='submit'>🗑️</button></form>{% endif %}
      </div>
      {% endif %}
    {% else %}<div class='card'>Nessuna notifica in questa sezione.</div>{% endfor %}</div>
    <script>document.querySelectorAll('.notice-row[data-href]').forEach(function(row){row.addEventListener('click',function(e){if(e.target.closest('form,button,a,input'))return;window.location.href=row.dataset.href;});});</script>"""
    return page("Centro notifiche",body,rows=rows,view=view,counts=counts)


@app.get("/notifications/sales-group")
@login_required
def notification_sales_group():
    seller=(request.args.get('seller') or '').strip()
    minute=(request.args.get('minute') or '').strip()[:16]
    if not seller or not minute:
        flash('Gruppo notifiche non valido.')
        return redirect(url_for('notification_center'))
    with connect() as db:
        rows=db.execute("""SELECT * FROM notifications
                           WHERE recipient_user_id=? AND notification_type='sale'
                             AND substr(created_at,1,16)=? AND message LIKE ?
                           ORDER BY created_at,id""",(session.get('user_id'),minute,seller+' · %')).fetchall()
        if not rows:
            flash('Gruppo notifiche non trovato.')
            return redirect(url_for('notification_center'))
        db.execute("""UPDATE notifications SET read_at=COALESCE(read_at,CURRENT_TIMESTAMP)
                      WHERE recipient_user_id=? AND notification_type='sale'
                        AND substr(created_at,1,16)=? AND message LIKE ?""",(session.get('user_id'),minute,seller+' · %'))
        sales=[]
        grand_total=0.0
        for n in rows:
            sale=db.execute("SELECT * FROM sales WHERE id=?",(n['reference_id'],)).fetchone()
            if not sale: continue
            sale_number=sale['sale_number']
            if sale_number:
                items=db.execute("SELECT * FROM sales WHERE sale_number=? ORDER BY id",(sale_number,)).fetchall()
            else:
                items=[sale]
            total=sum(float(x['quantity'] or 0)*float(x['unit_price'] or 0) for x in items)
            grand_total+=total
            sales.append({'notification':dict(n),'sale':dict(sale),'items':[dict(x) for x in items],'total':total})
        db.commit()
    body="""<h1>💰 {{seller}} · {{sales|length}} vendite</h1><div class='card'><p><b>Periodo:</b> {{minute}}</p><div class='metric'>Totale € {{'%.2f'|format(grand_total)}}</div></div>{% for s in sales %}<div class='card'><h2>{{s.sale.sale_number or ('Vendita #' ~ s.sale.id)}}</h2><p>Pagamento: <b>{{s.sale.payment_method or 'Altro'}}</b><br>{{s.sale.created_at|rome_time}}</p>{% for x in s.items %}<p><b>{{x.product_code}}</b> · {{x.quantity}} × € {{'%.2f'|format(x.unit_price)}}{% if x.original_unit_price and x.original_unit_price != x.unit_price %}<br><small>Listino € {{'%.2f'|format(x.original_unit_price)}} · {{x.discount_reason or 'sconto'}}{% if x.authorized_by_username %} · autorizzato da {{x.authorized_by_username}}{% endif %}</small>{% endif %}</p>{% endfor %}<hr><b>Totale vendita € {{'%.2f'|format(s.total)}}</b></div>{% endfor %}<p><a href='{{url_for("notification_center",view="read")}}'>← Notifiche lette</a></p>"""
    return page('Dettaglio vendite raggruppate',body,seller=seller,minute=minute,sales=sales,grand_total=grand_total)


@app.post("/notifications/sales-group/archive")
@login_required
def archive_notification_group():
    seller=(request.form.get('seller') or '').strip()
    minute=(request.form.get('minute') or '').strip()[:16]
    with connect() as db:
        _ensure_notifications(db)
        db.execute("""UPDATE notifications SET read_at=COALESCE(read_at,CURRENT_TIMESTAMP),
                      archived_at=COALESCE(archived_at,CURRENT_TIMESTAMP),
                      archived_by_user_id=?,archived_by_username=?
                      WHERE recipient_user_id=? AND notification_type='sale'
                        AND substr(created_at,1,16)=? AND message LIKE ? AND archived_at IS NULL""",
                   (session.get('user_id'),session.get('user'),session.get('user_id'),minute,seller+' · %'))
        db.commit()
    return redirect(url_for('notification_center',view='archive'))

@app.get("/notifications/<int:notification_id>")
@login_required
def notification_detail(notification_id):
    with connect() as db:
        _ensure_notifications(db)
        n=db.execute("SELECT * FROM notifications WHERE id=? AND recipient_user_id=?",(notification_id,session.get('user_id'))).fetchone()
        if not n:
            flash('Notifica non trovata.'); return redirect(url_for('notification_center'))
        db.execute("UPDATE notifications SET read_at=COALESCE(read_at,CURRENT_TIMESTAMP) WHERE id=?",(notification_id,))
        detail=None; items=[]
        if n['reference_type']=='discount': detail=db.execute("SELECT * FROM discount_requests WHERE id=?",(n['reference_id'],)).fetchone()
        elif n['reference_type']=='sale':
            detail=db.execute("SELECT * FROM sales WHERE id=?",(n['reference_id'],)).fetchone()
            if detail: items=db.execute("SELECT * FROM sales WHERE sale_number=? OR (sale_number IS NULL AND id=?) ORDER BY id",(detail['sale_number'],detail['id'])).fetchall()
        db.commit()
    if n['reference_type']=='discount' and detail:
        body="""<h1>{{n.title}}</h1><div class='card'><h2>{{detail.product_code}}</h2><p>Richiesta da <b>{{detail.requester_username}}</b></p><p>Listino € {{'%.2f'|format(detail.original_price)}} → <b>€ {{'%.2f'|format(detail.requested_price)}}</b><br>Sconto {{'%.1f'|format((1-detail.requested_price/detail.original_price)*100 if detail.original_price else 0)}}%</p><p>Motivo: {{detail.reason or 'Altro'}}<br>Stato: <b>{{detail.status}}</b>{% if detail.approver_username %}<br>Gestita da {{detail.approver_username}}{% endif %}</p>{% if session.get('role') in ('admin','manager') and detail.status=='In attesa' %}<a class='success' href='{{url_for("discount_approvals")}}'>Apri autorizzazione</a>{% elif session.get('role')=='seller' and detail.status in ('Approvata','Applicata') %}<form method='post' action='{{url_for("return_discount_to_cart",request_id=detail.id)}}'><button class='success'>Torna al carrello</button></form>{% endif %}</div><p><a href='{{url_for("notification_center")}}'>← Notifiche</a></p>"""
        return page('Dettaglio notifica',body,n=n,detail=detail)
    if n['reference_type']=='sale' and detail:
        total=sum(float(x['unit_price'] or 0)*int(x['quantity'] or 0) for x in items)
        body="""<h1>💰 Dettaglio vendita</h1><div class='card'><h2>{{detail.sale_number or ('Vendita #' ~ detail.id)}}</h2><p>Venditore: <b>{{detail.username}}</b><br>Pagamento: <b>{{detail.payment_method or 'Altro'}}</b><br>{{detail.created_at|rome_time}}</p>{% for x in items %}<p><b>{{x.product_code}}</b> · {{x.quantity}} × € {{'%.2f'|format(x.unit_price)}}{% if x.original_unit_price and x.original_unit_price != x.unit_price %}<br><small>Listino € {{'%.2f'|format(x.original_unit_price)}} · {{x.discount_reason or 'sconto'}}{% if x.authorized_by_username %} · autorizzato da {{x.authorized_by_username}}{% endif %}</small>{% endif %}</p>{% endfor %}<hr><div class='metric'>€ {{'%.2f'|format(total)}}</div></div><p><a href='{{url_for("notification_center")}}'>← Notifiche</a></p>"""
        return page('Dettaglio vendita',body,n=n,detail=detail,items=items,total=total)
    return page('Dettaglio notifica',"<h1>{{n.title}}</h1><div class='card'>{{n.message}}<br><small>{{n.created_at|rome_time}}</small></div>",n=n)

@app.post("/notifications/<int:notification_id>/archive")
@login_required
def archive_notification(notification_id):
    with connect() as db:
        _ensure_notifications(db)
        db.execute("UPDATE notifications SET archived_at=CURRENT_TIMESTAMP,archived_by_user_id=?,archived_by_username=? WHERE id=? AND recipient_user_id=? AND archived_at IS NULL",(session.get('user_id'),session.get('user'),notification_id,session.get('user_id')))
        db.commit()
    flash('Notifica archiviata. Rimane nello storico.')
    return redirect(request.referrer or url_for('notification_center'))

@app.route("/login",methods=["GET","POST"])
def login():
    if request.method=="POST":
        with connect() as db:
            badge_payload=request.form.get("badge_payload","")
            if badge_payload:
                user=find_badge_user(db,badge_payload)
                if user:
                    start_user_session(db,user,"Login badge")
                    return redirect(url_for("home"))
                flash("Badge non valido, revocato o account disattivato.")
            else:
                username=request.form.get("username","").strip()
                password=request.form.get("password","")
                user=db.execute("SELECT * FROM users WHERE username=? COLLATE NOCASE AND active=1",(username,)).fetchone()

                # L'account tecnico Admin usa sempre la password configurata su Render.
                # Non dipende dall'hash eventualmente presente nel database.
                if username.lower()=="admin":
                    admin_password=os.environ.get("TBS_ADMIN_PASSWORD","").strip()
                    admin_user=db.execute("SELECT * FROM users WHERE role='admin' AND active=1 ORDER BY is_system_admin DESC,id LIMIT 1").fetchone()
                    if not admin_password:
                        flash("Accesso Admin non configurato: manca TBS_ADMIN_PASSWORD su Render.","error")
                    elif admin_user and secrets.compare_digest(password,admin_password):
                        start_user_session(db,admin_user,"Login Admin tecnico")
                        return redirect(url_for("home"))
                    else:
                        flash("Password Admin non corretta.","error")
                elif user and user["password_hash"] and check_password_hash(user["password_hash"],password):
                    start_user_session(db,user,"Login")
                    return redirect(url_for("home"))
                else:
                    flash("Credenziali non corrette o account disattivato.","error")
    scanner=badge_scanner_html(url_for("login"),"Accedi con badge",auto_start=True)
    return login_page("Accesso · TBS Gestionale",'''<section class="login-intro"><span class="login-eyebrow">ACCESSO SICURO</span><h1>Benvenuto in<br><em>TBS ONE.</em></h1><p>Inquadra il badge oppure accedi con le tue credenziali.</p></section>{{scanner|safe}}<details class="card" style="max-width:520px;margin:16px auto"><summary style="cursor:pointer;font-weight:800;padding:4px 2px">Accedi con username e password</summary><form method="post" style="margin-top:16px"><p><input name="username" autocomplete="username" placeholder="Utente" required></p><p class="password-wrap"><input id="loginPassword" name="password" type="password" autocomplete="current-password" placeholder="Password" required><button class="password-toggle" type="button" aria-label="Mostra password" onclick="const p=document.getElementById('loginPassword');p.type=p.type==='password'?'text':'password';this.textContent=p.type==='password'?'👁':'🙈'">👁</button></p><button class="login-submit">Accedi</button></form><p class="muted" style="text-align:center;margin-bottom:0">Blocco automatico dopo {{minutes}} minuti.</p></details>''',minutes=max(1,LOCK_TIMEOUT_SECONDS//60),scanner=scanner)

@app.get("/lock")
@login_required
def lock_register():
    automatic=request.args.get("auto")=="1"; username=session.get("user"); user_id=session.get("user_id"); role=session.get("role")
    with connect() as db:
        cart_id=suspend_current_cart(db,"Blocco automatico" if automatic else "Blocco manuale")
        log_action(db,"Blocco automatico" if automatic else "Blocco manuale",details=f"Carrello sospeso: {cart_id}" if cart_id else "Nessun carrello"); db.commit()
    session.clear(); session["locked"]=True; session["locked_user_id"]=user_id; session["locked_username"]=username; session["locked_role"]=role; session["locked_cart_id"]=cart_id
    return redirect(url_for("unlock_register"))

@app.route("/unlock",methods=["GET","POST"])
def unlock_register():
    if not session.get("locked"): return redirect(url_for("login"))
    locked_user_id=session.get("locked_user_id"); locked_username=session.get("locked_username"); locked_cart_id=session.get("locked_cart_id")
    if request.method=="POST":
        with connect() as db:
            badge_payload=request.form.get("badge_payload","")
            unlock_username=request.form.get("username","").strip()
            unlock_password=request.form.get("password","")
            user=find_badge_user(db,badge_payload) if badge_payload else db.execute("SELECT * FROM users WHERE username=? COLLATE NOCASE AND active=1",(unlock_username,)).fetchone()
            if badge_payload:
                valid=bool(user)
            elif unlock_username.lower()=="admin":
                admin_password=os.environ.get("TBS_ADMIN_PASSWORD","").strip()
                user=db.execute("SELECT * FROM users WHERE role='admin' AND active=1 ORDER BY is_system_admin DESC,id LIMIT 1").fetchone()
                valid=bool(user and admin_password and secrets.compare_digest(unlock_password,admin_password))
            else:
                valid=bool(user and user["password_hash"] and check_password_hash(user["password_hash"],unlock_password))
            if valid:
                same_user=user["id"]==locked_user_id
                session.clear(); session.permanent=True; session["user_id"]=user["id"]; session["user"]=user["username"]; session["role"]=user["role"]
                if same_user and locked_cart_id:
                    restored=restore_suspended_cart(db,locked_cart_id)
                    if restored: session["cart"]=restored[0]
                log_action(db,"Sblocco cassa con badge" if badge_payload else "Sblocco cassa",details=("Stesso utente" if same_user else f"Sessione precedente: {locked_username}")); db.commit()
                if not same_user and locked_cart_id: flash(f"Il carrello di {locked_username} è rimasto sospeso e non è stato perso.")
                return redirect(url_for("cart") if same_user and locked_cart_id else url_for("home"))
        flash("Badge o credenziali non validi; account eventualmente disattivato.")
    scanner=badge_scanner_html(url_for("unlock_register"),"Sblocca con badge",auto_start=True,privacy_blur=True)
    return page("Cassa bloccata",'''<style>
.lock-head{max-width:560px;margin:22px auto 14px;padding:22px;text-align:center;border:1px solid rgba(232,190,91,.42);border-radius:22px;background:linear-gradient(145deg,#17140d,#080808)}
.lock-head .lock-symbol{display:grid;width:62px;height:62px;margin:0 auto 12px;place-items:center;border:1px solid rgba(232,190,91,.55);border-radius:20px;background:#080808;font-size:30px}
.lock-head h1{margin:0;color:#fff}
.lock-head p{margin:9px 0 0;color:#d8d2c8}
.lock-head b{color:#f1ca68}
</style><div class="lock-head"><div class="lock-symbol">🔒</div><h1>Cassa bloccata</h1><p>Sessione di <b>{{locked_username}}</b> protetta. Avvicina il badge al riquadro.</p>{% if has_cart %}<p class="flash">Il carrello è stato salvato e non andrà perso.</p>{% endif %}</div>{{scanner|safe}}<details class="card" style="max-width:520px;margin:16px auto"><summary style="cursor:pointer;font-weight:700;padding:6px">Sblocca con username e password</summary><form method="post" style="margin-top:14px"><p><input name="username" value="{{locked_username}}" required></p><p><input name="password" type="password" placeholder="Password" required></p><button>Sblocca cassa</button></form><p class="muted">Un altro utente può accedere: il carrello precedente resterà sospeso.</p></details>''',locked_username=locked_username,has_cart=bool(locked_cart_id),scanner=scanner)

@app.get("/logout")
def logout():
    if session.get("user_id"):
        with connect() as db: log_action(db,"Logout"); db.commit()
    session.clear(); return redirect(url_for("login"))

@app.get("/home")
@login_required
def home():
    """Landing page stabile e coerente con il ruolo."""
    role=(session.get("role") or "").strip().lower()
    if role == "seller":
        return redirect(url_for("pos"))
    if role in ("admin","manager"):
        return redirect(url_for("dashboard_smart"))
    session.clear()
    flash("Ruolo utente non riconosciuto.","error")
    return redirect(url_for("login"))

@app.get("/admin")
@login_required
@role_required("admin","manager")
def dashboard():
    with connect() as db:
        r=db.execute("SELECT COUNT(*) FROM products WHERE active=1").fetchone()[0]
        p=db.execute("SELECT COALESCE(SUM(quantity),0) FROM products WHERE active=1").fetchone()[0]
        l=db.execute("SELECT COUNT(*) FROM products WHERE active=1 AND quantity<=1").fetchone()[0]
        f=db.execute("SELECT COUNT(*) FROM products WHERE active=1 AND COALESCE(photo_data,'')<>''").fetchone()[0]
        today=db.execute("""SELECT COALESCE(SUM(quantity),0) pieces,
            COALESCE(SUM(quantity*unit_price),0) revenue,
            COUNT(DISTINCT COALESCE(sale_number,id)) receipts
            FROM sales WHERE status='Confermata' AND date(created_at,'localtime')=date('now','localtime')""").fetchone()
        week_revenue=db.execute("""SELECT COALESCE(SUM(quantity*unit_price),0)
            FROM sales WHERE status='Confermata' AND datetime(created_at,'localtime')>=datetime('now','localtime','-7 days')""").fetchone()[0]
        low_stock=db.execute("""SELECT * FROM products WHERE active=1 AND quantity<=min_stock
            ORDER BY quantity ASC, brand_code LIMIT 8""").fetchall()
        top_products=db.execute("""SELECT product_code, SUM(quantity) pieces,
            SUM(quantity*unit_price) revenue FROM sales
            WHERE status='Confermata' AND datetime(created_at,'localtime')>=datetime('now','localtime','-30 days')
            GROUP BY product_code ORDER BY pieces DESC, revenue DESC LIMIT 5""").fetchall()
        recent_sales=db.execute("""SELECT sale_number,username,created_at,payment_method,channel,
            SUM(quantity) pieces,SUM(quantity*unit_price) total
            FROM sales WHERE status='Confermata'
            GROUP BY COALESCE(sale_number,id) ORDER BY MAX(id) DESC LIMIT 5""").fetchall()
        recent=db.execute("SELECT * FROM audit_log ORDER BY id DESC LIMIT 5").fetchall() if session.get("role")=="admin" else []
        my_sales=db.execute("SELECT * FROM sales WHERE user_id=? ORDER BY id DESC LIMIT 5",(session.get("user_id"),)).fetchall() if session.get("role")=="seller" else []
        pending_catalog_requests=db.execute("SELECT COUNT(*) FROM supplier_catalog_requests WHERE status IN ('Da ordinare','Nuovo')").fetchone()[0]
    return page("Dashboard",'''<style>
.dash-head{display:flex;justify-content:space-between;gap:14px;align-items:flex-start;margin-bottom:18px}.dash-head h1{margin:0}.quick-actions{display:flex;gap:9px;flex-wrap:wrap}.quick-actions a{padding:11px 14px;border-radius:10px;color:white;text-decoration:none;font-weight:850}.kpi-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:18px}.kpi{padding:18px;border-radius:16px;background:white;border:1px solid #e5e7eb;box-shadow:0 8px 26px rgba(17,24,39,.06)}.kpi .metric{font-size:clamp(30px,6vw,48px);line-height:1.05;margin:7px 0}.kpi strong{font-size:14px;color:#4b5563}.dash-two{display:grid;grid-template-columns:1.15fr .85fr;gap:16px}.stock-row,.sale-row,.top-row{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:center;padding:12px 0;border-bottom:1px solid #edf0f3}.stock-row:last-child,.sale-row:last-child,.top-row:last-child{border-bottom:0}.stock-pill{font-weight:900;padding:6px 10px;border-radius:999px;background:#fff0bf;color:#805b00}.stock-zero{background:#f8d7da;color:#8a1c26}.rank{display:inline-flex;width:28px;height:28px;border-radius:50%;background:#111827;color:white;align-items:center;justify-content:center;font-weight:900;margin-right:8px}.empty-mini{padding:18px;text-align:center;color:#6b7280}@media(max-width:800px){.dash-head{display:block}.quick-actions{margin-top:14px}.kpi-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.dash-two{grid-template-columns:1fr}}@media(max-width:440px){.kpi-grid{grid-template-columns:1fr 1fr}.kpi{padding:14px}.quick-actions a{flex:1;text-align:center}}
</style><div class="dash-head"><div class="welcome-block"><span class="eyebrow">PANORAMICA OPERATIVA</span><h1>Bentornato, <span class="welcome-name">{{session.get('user')}}</span>.</h1><p class="muted">Tutto ciò che serve per gestire la giornata.</p>{% if pending_catalog_requests %}<p><a class="order-alert" href="{{url_for('catalog_requests')}}">{{pending_catalog_requests}} nuovi ordini cliente</a></p>{% endif %}</div><div class="quick-actions"><a href="{{url_for('price_check')}}"><span>€</span><b>Assistente</b><small>Prezzi e disponibilità</small></a><a href="{{url_for('cart')}}"><span>＋</span><b>Carrello</b><small>Vendita rapida</small></a><a href="{{url_for('products')}}"><span>◇</span><b>Catalogo</b><small>Magazzino prodotti</small></a><a href="{{url_for('scan_product')}}"><span>⌗</span><b>Scanner</b><small>Leggi QR prodotto</small></a></div></div><div class="kpi-grid"><div class="kpi"><div class="kpi-top"><span>€</span><strong>Oggi</strong></div><div class="metric">€ {{'%.2f'|format(today.revenue)}}</div><span class="muted">{{today.receipts}} vendite · {{today.pieces}} pezzi</span></div><div class="kpi"><div class="kpi-top"><span>↗</span><strong>7 giorni</strong></div><div class="metric">€ {{'%.2f'|format(week_revenue)}}</div><span class="muted">Valore vendite confermate</span></div><div class="kpi"><div class="kpi-top"><span>◇</span><strong>Disponibilità</strong></div><div class="metric">{{p}}</div><span class="muted">{{r}} referenze attive</span></div><div class="kpi"><div class="kpi-top"><span>!</span><strong>Scorte critiche</strong></div><div class="metric">{{l}}</div><span class="muted">Quantità ≤ 1</span></div></div><div class="dash-two"><div><div class="card"><h2>⚠️ Da controllare</h2>{% if low_stock %}{% for x in low_stock %}<div class="stock-row"><div><b>{{x.brand_code}}</b><br><small class="muted">{{x.category or 'Altro'}}{% if x.location %} · 📍 {{x.location}}{% endif %}</small></div><span class="stock-pill {% if x.quantity<=0 %}stock-zero{% endif %}">{{x.quantity}} pz</span></div>{% endfor %}<p><a href="{{url_for('products')}}">Apri il magazzino →</a></p>{% else %}<div class="empty-mini">Nessuna scorta critica.</div>{% endif %}</div><div class="card"><h2>🏆 Più venduti · 30 giorni</h2>{% if top_products %}{% for x in top_products %}<div class="top-row"><div><span class="rank">{{loop.index}}</span><b>{{x.product_code}}</b></div><div style="text-align:right"><b>{{x.pieces}} pz</b><br><small class="muted">€ {{'%.2f'|format(x.revenue)}}</small></div></div>{% endfor %}{% else %}<div class="empty-mini">Non ci sono ancora vendite nel periodo.</div>{% endif %}</div></div><div><div class="card"><h2>🧾 Ultime vendite</h2>{% if recent_sales %}{% for x in recent_sales %}<div class="sale-row"><div><b>{{x.sale_number or 'Vendita'}}</b><br><small class="muted">{{x.created_at|rome_time}} · {{x.username}}<br>{{x.payment_method or 'Altro'}} · {{x.channel or 'Negozio'}}</small></div><div style="text-align:right"><b>€ {{'%.2f'|format(x.total)}}</b><br><small>{{x.pieces}} pz</small></div></div>{% endfor %}<p><a href="{{url_for('sales_log')}}">Registro completo →</a></p>{% else %}<div class="empty-mini">Nessuna vendita registrata.</div>{% endif %}</div><div class="card"><h2>📘 Ordinabili</h2><p>Consulta il catalogo fornitore e crea ordini cliente con consegna indicativa 15–20 giorni.</p><a class="view" href="{{url_for('supplier_catalog')}}" style="padding:11px 16px;border-radius:9px;text-decoration:none;color:white;display:inline-block;font-weight:bold">Apri catalogo</a></div></div></div>{% if role == 'seller' and my_sales %}<div class="card"><h3>Le tue ultime operazioni</h3>{% for x in my_sales %}<p><b>{{x.product_code}}</b> · {{x.quantity}} pz · € {{'%.2f'|format(x.unit_price)}}<br><span class="muted">{{x.created_at|rome_time}}</span></p>{% endfor %}</div>{% endif %}{% if recent %}<div class="card"><h3>Storico amministrativo recente</h3>{% for x in recent %}<p><b>{{x.username}}</b> · {{x.action}}{% if x.product_code %} · {{x.product_code}}{% endif %}<br><span class="muted">{{x.created_at|rome_time}} {{x.details or ''}}</span></p>{% endfor %}</div>{% endif %}''',r=r,p=p,l=l,f=f,today=today,week_revenue=week_revenue,low_stock=low_stock,top_products=top_products,recent_sales=recent_sales,recent=recent,my_sales=my_sales,role=session.get("role"),role_label=ROLE_LABELS.get(session.get("role"),session.get("role")),pending_catalog_requests=pending_catalog_requests)


