@app.post("/discount-request/<int:request_id>/return-cart")
@login_required
def return_discount_to_cart(request_id):
    """Ripristina nel carrello del venditore l'articolo con il prezzo autorizzato."""
    if session.get("role") != "seller":
        return redirect(url_for("cart"))
    with connect() as db:
        req=db.execute("SELECT * FROM discount_requests WHERE id=? AND requester_user_id=?",(request_id,session.get("user_id"))).fetchone()
        if not req or req["status"] not in ("Approvata","Applicata"):
            flash("Autorizzazione non disponibile.")
            return redirect(url_for("cart"))
        product=db.execute("SELECT id,quantity FROM products WHERE id=?",(req["product_id"],)).fetchone()
        if not product:
            flash("Il prodotto non è più disponibile nel catalogo.")
            return redirect(url_for("cart"))
        raw=dict(session.get("cart",{}))
        key=str(product["id"])
        if key not in raw:
            if int(product["quantity"] or 0) <= 0:
                flash("Il prodotto non è disponibile in magazzino.")
                return redirect(url_for("cart"))
            raw[key]=1
            session["cart"]=raw
        cp=dict(session.get("cart_prices",{}))
        cp[key]={"price":float(req["requested_price"]),"reason":req["reason"],"authorized_by_user_id":req["approver_user_id"],"authorized_by_username":req["approver_username"]}
        session["cart_prices"]=cp
        session.modified=True
        if req["status"] == "Approvata":
            db.execute("UPDATE discount_requests SET status='Applicata',applied_at=CURRENT_TIMESTAMP WHERE id=?",(request_id,))
        _ensure_notifications(db)
        db.execute("""UPDATE notifications
                      SET read_at=COALESCE(read_at,CURRENT_TIMESTAMP)
                      WHERE recipient_user_id=? AND reference_type='discount' AND reference_id=? AND archived_at IS NULL""",
                   (session.get("user_id"),request_id))
        db.commit()
    flash("Articolo e prezzo autorizzato ripristinati nel carrello.")
    return redirect(url_for("cart"))

@app.get("/cart")
@login_required
def cart():
    raw=session.get("cart",{})
    discount_feedback=[]
    has_pending_discount=False
    if session.get("role") == "seller":
        with connect() as db:
            discount_rows=db.execute("""SELECT * FROM discount_requests
                WHERE requester_user_id=? AND status IN ('In attesa','Approvata','Applicata','Controproposta','Rifiutata')
                ORDER BY id DESC LIMIT 12""",(session.get("user_id"),)).fetchall()
            for req in discount_rows:
                status=req["status"]
                if status == "In attesa":
                    has_pending_discount=True
                if status == "Approvata" and str(req["product_id"]) in raw:
                    cp=dict(session.get("cart_prices",{}))
                    cp[str(req["product_id"])]= {
                        "price":req["requested_price"],
                        "reason":req["reason"],
                        "authorized_by_user_id":req["approver_user_id"],
                        "authorized_by_username":req["approver_username"]
                    }
                    session["cart_prices"]=cp
                    session.modified=True
                    db.execute("UPDATE discount_requests SET status='Applicata',applied_at=CURRENT_TIMESTAMP WHERE id=? AND status='Approvata'",(req["id"],))
                    status="Applicata"
                discount_feedback.append({
                    "id":req["id"],
                    "product_id":req["product_id"],
                    "status":status,
                    "product_code":req["product_code"],
                    "original_price":req["original_price"],
                    "requested_price":req["requested_price"],
                    "counter_price":req["counter_price"],
                    "reason":req["reason"],
                    "approver_username":req["approver_username"],
                    "created_at":req["created_at"],
                    "decided_at":req["decided_at"],
                    "in_cart":str(req["product_id"]) in raw
                })
            db.commit()
    ids=[]
    for key in raw:
        try: ids.append(int(key))
        except (TypeError,ValueError): pass
    rows=[]; total=0.0; total_qty=0
    if ids:
        placeholders=",".join("?" for _ in ids)
        with connect() as db:
            products=db.execute(f"SELECT * FROM products WHERE id IN ({placeholders})",ids).fetchall()
        by_id={x["id"]:x for x in products}
        for product_id in ids:
            p=by_id.get(product_id)
            if not p: continue
            qty=max(1,int(raw.get(str(product_id),1)))
            pd=_cart_price_data(product_id,p["price"])
            subtotal=qty*pd["price"]
            rows.append({"product":p,"quantity":qty,"unit_price":pd["price"],"original_price":p["price"],"reason":pd["reason"],"authorized_by":pd["authorized_by_username"],"subtotal":subtotal})
            total+=subtotal; total_qty+=qty
    all_discounted_authorized=bool(rows) and all((x["unit_price"] != x["original_price"] and x["authorized_by"]) for x in rows)
    return page("Carrello",'''<style>
.discount-status-list{display:grid;gap:12px;margin:14px 0 18px}.discount-result{display:grid;grid-template-columns:52px 1fr;gap:12px;align-items:center;border-radius:16px;padding:16px;border:2px solid}.discount-return{width:100%;text-align:left;font:inherit;cursor:pointer;background:inherit;color:inherit}.discount-return:active{transform:scale(.99)}.discount-result .result-icon{font-size:34px;text-align:center}.discount-result b{font-size:20px}.discount-result.approved{background:#eafaf2;border-color:#10a36d;color:#07583d}.discount-result.rejected{background:#fff0f0;border-color:#d52b2b;color:#8b1515}.discount-result.pending{background:#fff8df;border-color:#d6a72c;color:#654b07}.discount-result small{font-weight:700}.cart-price-box{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:8px 0}.edit-price-btn{background:linear-gradient(135deg,#d6b15f,#a97927);color:#17120a;border:0;border-radius:10px;padding:10px 14px;font-weight:900}.approved-price-badge{display:inline-flex;align-items:center;gap:6px;background:#eafaf2;border:1px solid #10a36d;color:#07583d;border-radius:10px;padding:10px 12px;font-weight:900}.approved-price-note{background:#eafaf2;border:1px solid #10a36d;border-radius:10px;padding:10px;margin:8px 0;color:#07583d}.discount-note{background:#fff4d7;border:1px solid #d7b15f;border-radius:10px;padding:10px;margin:8px 0;color:#503a0d}.price-modal-wrap{position:fixed;inset:0;background:#000b;display:none;align-items:center;justify-content:center;z-index:2000}.price-modal-wrap.open{display:flex}.price-modal{width:min(480px,92vw);background:#fff;border-radius:20px;padding:24px;box-shadow:0 30px 90px #0008}.price-modal label{display:block;font-weight:800;margin-top:12px}.price-modal input,.price-modal select{width:100%;margin-top:6px}.price-modal-actions{display:grid;grid-template-columns:2fr 1fr;gap:10px;margin-top:18px}.payment-buttons{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin:12px 0}.payment-buttons label{display:block}.payment-buttons input{position:absolute;opacity:0}.payment-buttons span{display:block;text-align:center;padding:15px;border:2px solid #d8dde5;border-radius:12px;font-weight:900;cursor:pointer}.payment-buttons input:checked+span{border-color:#b88a2a;background:#fff4d7;color:#4a350b}@media(max-width:650px){.payment-buttons{grid-template-columns:1fr}.price-modal-actions{grid-template-columns:1fr}}
</style><h1>Carrello vendita</h1>{% if session.get('role') == 'seller' and discount_feedback %}<div class="discount-status-list">{% for d in discount_feedback %}{% if d.status in ('Applicata','Approvata') and not d.in_cart %}<form method="post" action="{{url_for('return_discount_to_cart',request_id=d.id)}}" style="margin:0"><button type="submit" class="discount-result approved discount-return"><div class="result-icon">✅</div><div><b>SCONTO AUTORIZZATO</b><br><strong>{{d.product_code}}</strong> · € {{'%.2f'|format(d.original_price)}} → <strong>€ {{'%.2f'|format(d.requested_price)}}</strong><br><span>Autorizzato da {{d.approver_username or 'Admin/Gestore'}}{% if d.decided_at %} · {{d.decided_at|rome_time}}{% endif %}</span><br><small>TOCCA QUI PER TORNARE AL CARRELLO</small></div></button></form>{% elif d.status == 'Controproposta' %}<div class="discount-result pending"><div class="result-icon">↔</div><div><b>CONTROPROPOSTA RICEVUTA</b><br><strong>{{d.product_code}}</strong> · proposta <strong>€ {{'%.2f'|format(d.counter_price)}}</strong><br><small>Apri la campanella o la schermata di attesa per accettare o rifiutare.</small></div></div>{% elif d.status == 'Rifiutata' %}<div class="discount-result rejected"><div class="result-icon">❌</div><div><b>SCONTO RIFIUTATO</b><br><strong>{{d.product_code}}</strong> · richiesto € {{'%.2f'|format(d.requested_price)}}<br><span>{% if d.approver_username %}Decisione di {{d.approver_username}}{% else %}Richiesta non approvata{% endif %}{% if d.decided_at %} · {{d.decided_at|rome_time}}{% endif %}</span><br><small>Rimane valido il prezzo di listino.</small></div></div>{% elif d.status == 'In attesa' %}<div class="discount-result pending"><div class="result-icon">⏳</div><div><b>AUTORIZZAZIONE IN ATTESA</b><br><strong>{{d.product_code}}</strong> · € {{'%.2f'|format(d.original_price)}} → € {{'%.2f'|format(d.requested_price)}}<br><small>La pagina si aggiorna automaticamente quando Admin o Gestore decide.</small></div></div>{% endif %}{% endfor %}</div>{% endif %}{% if rows %}<div class="card">{% for x in rows %}<div style="display:grid;grid-template-columns:80px 1fr;gap:14px;align-items:center;margin-bottom:18px">{% if x.product.photo_data %}<img src="{{x.product.photo_data}}" style="width:80px;height:80px;object-fit:contain;border-radius:10px">{% endif %}<div><b>{{x.product.brand_code}}</b><br><span class="muted">Codice interno: {{x.product.brand_code}}{% if session.get('role') in ('admin','manager') %} · Codice fornitore: {{x.product.supplier_code}}{% endif %} · disponibili {{x.product.quantity}}</span><div class="cart-price-box"><span>{% if x.unit_price != x.original_price %}<s>€ {{'%.2f'|format(x.original_price)}}</s> <b>€ {{'%.2f'|format(x.unit_price)}} cad.</b>{% else %}<b>€ {{'%.2f'|format(x.original_price)}} cad.</b>{% endif %}</span>{% if session.get('role') == 'seller' %}{% if x.authorized_by and x.unit_price != x.original_price %}{% else %}<button type="button" class="edit-price-btn" onclick='openCartPrice({{x.product.id}}, {{x.product.brand_code|tojson}}, {{x.original_price}}, {{x.unit_price}})'>💸 Richiedi sconto</button>{% endif %}{% else %}<button type="button" class="edit-price-btn" onclick='openCartPrice({{x.product.id}}, {{x.product.brand_code|tojson}}, {{x.original_price}}, {{x.unit_price}})'>✏️ Modifica prezzo</button>{% endif %}</div>{% if x.unit_price != x.original_price %}{% if x.authorized_by %}<div class="approved-price-note"><b>✅ Sconto autorizzato</b><br>Listino € {{'%.2f'|format(x.original_price)}} → vendita <b>€ {{'%.2f'|format(x.unit_price)}}</b><br>{{x.reason or 'Altro'}} · autorizzato da {{x.authorized_by}}</div>{% else %}<div class="discount-note"><b>Prezzo personalizzato</b><br>Listino € {{'%.2f'|format(x.original_price)}} → vendita € {{'%.2f'|format(x.unit_price)}}<br>{{x.reason or 'Altro'}}</div>{% endif %}{% endif %}<form class="inline" method="post" action="{{url_for('update_cart',product_id=x.product.id)}}"><input style="max-width:100px" name="quantity" type="number" min="1" max="{{x.product.quantity}}" value="{{x.quantity}}"><button class="secondary">Aggiorna</button></form><form method="post" action="{{url_for('remove_from_cart',product_id=x.product.id)}}"><button class="danger">Rimuovi</button></form><b>Subtotale: € {{'%.2f'|format(x.subtotal)}}</b></div></div><hr>{% endfor %}</div><div class="card"><div class="muted">Articoli</div><div class="metric">{{total_qty}}</div><div class="muted">Totale vendita</div><div class="metric">€ {{'%.2f'|format(total)}}</div>{% if session.get('role') == 'seller' and not all_discounted_authorized %}<div class="discount-note" style="margin:14px 0"><b>Devi applicare uno sconto?</b><br>Premi <b>💸 Richiedi sconto</b> accanto all'articolo interessato. Admin o Gestore riceveranno la richiesta sul proprio telefono.</div>{% endif %}<form method="post" action="{{url_for('checkout_cart')}}" onsubmit="return confirm('Confermi la vendita?')"><div class="payment-buttons"><label><input type="radio" name="payment_method" value="Contanti" checked><span>💶 CONTANTI</span></label><label><input type="radio" name="payment_method" value="Bancomat"><span>💳 BANCOMAT</span></label><label><input type="radio" name="payment_method" value="Bonifico"><span>🏦 BONIFICO</span></label><label><input type="radio" name="payment_method" value="Altro"><span>••• ALTRO</span></label></div><input type="hidden" name="channel" value="Negozio"><button>Conferma vendita</button></form><form method="post" action="{{url_for('suspend_cart')}}"><button class="secondary">Sospendi vendita</button></form><form method="post" action="{{url_for('clear_cart')}}"><button class="secondary">Svuota carrello</button></form></div><div id="cartPriceModal" class="price-modal-wrap"><div class="price-modal"><h2>Modifica prezzo</h2><p id="cartPriceTitle"></p><form method="post" action="{{url_for('pos_set_price')}}"><input type="hidden" id="cartPricePid" name="product_id"><input type="hidden" name="return_to" value="cart"><label>Prezzo di listino<input id="cartPriceOriginal" readonly></label><label>Nuovo prezzo<input id="cartPriceNew" name="new_price" type="number" min="0" step="0.01" required></label><label>Motivo<select name="reason"><option>Cliente abituale</option><option>Amico</option><option>Promozione</option><option>Altro</option></select></label>{% if session.get('role') == 'seller' %}<div class="discount-note"><b>Autorizzazione remota</b><br>La richiesta verrà inviata ad Admin e Gestore. Potrai restare nel flusso del carrello mentre attendi la risposta.</div>{% endif %}<div class="price-modal-actions"><button class="edit-price-btn">{% if session.get('role') == 'seller' %}RICHIEDI AUTORIZZAZIONE{% else %}CONFERMA PREZZO{% endif %}</button><button type="button" class="secondary" onclick="closeCartPrice()">ANNULLA</button></div></form></div></div><script>function openCartPrice(id,name,original,current){cartPricePid.value=id;cartPriceTitle.textContent=name;cartPriceOriginal.value='€ '+Number(original).toFixed(2);cartPriceNew.value=Number(current).toFixed(2);cartPriceModal.classList.add('open');cartPriceNew.focus()}function closeCartPrice(){cartPriceModal.classList.remove('open')}cartPriceModal.addEventListener('click',function(e){if(e.target===this)closeCartPrice()}){% if has_pending_discount %}setTimeout(function(){location.reload()},4000);{% endif %}</script>{% else %}<div class="card"><p>Il carrello è vuoto.</p><a class="view" href="{{url_for('products')}}" style="padding:11px 16px;border-radius:9px;text-decoration:none;color:white;display:inline-block">Vai ai prodotti</a></div>{% endif %}''',rows=rows,total=total,total_qty=total_qty,discount_feedback=discount_feedback,has_pending_discount=has_pending_discount,all_discounted_authorized=all_discounted_authorized)

@app.post("/cart/add/<int:product_id>")
@login_required
def add_to_cart(product_id):
    try: qty=max(1,int(request.form.get("quantity",1)))
    except ValueError: qty=1
    with connect() as db: p=db.execute("SELECT * FROM products WHERE id=?",(product_id,)).fetchone()
    if not p or p["quantity"]<=0:
        flash("Prodotto non disponibile."); return redirect(request.referrer or url_for("products"))
    cart=dict(session.get("cart",{})); current=int(cart.get(str(product_id),0)); cart[str(product_id)]=min(current+qty,p["quantity"]); session["cart"]=cart; session.modified=True
    flash(f"{p['brand_code']} aggiunto al carrello.")
    return redirect(request.referrer or url_for("products"))

@app.post("/cart/update/<int:product_id>")
@login_required
def update_cart(product_id):
    try: qty=int(request.form.get("quantity",1))
    except ValueError: qty=1
    with connect() as db: p=db.execute("SELECT * FROM products WHERE id=?",(product_id,)).fetchone()
    cart=dict(session.get("cart",{}))
    if not p or qty<=0: cart.pop(str(product_id),None)
    else: cart[str(product_id)]=min(qty,p["quantity"])
    session["cart"]=cart; session.modified=True
    return redirect(url_for("cart"))

@app.post("/cart/remove/<int:product_id>")
@login_required
def remove_from_cart(product_id):
    cart=dict(session.get("cart",{})); cart.pop(str(product_id),None); session["cart"]=cart; prices=dict(session.get("cart_prices",{})); prices.pop(str(product_id),None); session["cart_prices"]=prices; session.modified=True
    return redirect(url_for("cart"))

@app.post("/cart/clear")
@login_required
def clear_cart():
    session.pop("cart",None); session.pop("cart_prices",None); session.pop("pending_price_override",None); session.modified=True; flash("Carrello svuotato.")
    return redirect(url_for("cart"))

@app.post("/cart/checkout")
@login_required
def checkout_cart():
    raw=dict(session.get("cart",{}))
    if not raw:
        flash("Il carrello è vuoto."); return redirect(url_for("cart"))
    payment=request.form.get("payment_method","Altro")
    channel=request.form.get("channel","Negozio")
    if payment not in ("Contanti","Bancomat","POS","Bonifico","Altro"): payment="Altro"
    if channel not in ("Negozio","Online"): channel="Negozio"
    with connect() as db:
        items=[]
        for key,requested in raw.items():
            try: product_id=int(key); qty=int(requested)
            except (TypeError,ValueError): continue
            p=db.execute("SELECT * FROM products WHERE id=?",(product_id,)).fetchone()
            if not p or qty<1 or p["quantity"]<qty:
                flash(f"Disponibilità insufficiente per {p['brand_code'] if p else 'un prodotto'}. Vendita non registrata.")
                return redirect(url_for("cart"))
            items.append((p,qty))
        if not items:
            flash("Nessun articolo valido nel carrello."); return redirect(url_for("cart"))
        sale_number=next_sale_number(db)
        total=0.0; pieces=0; used_discount_request_ids=[]
        for p,qty in items:
            pd=_cart_price_data(p["id"],p["price"]); unit_price=pd["price"]
            if session.get('role') == 'seller' and pd["authorized_by_username"]:
                used_req=db.execute("""SELECT id FROM discount_requests
                    WHERE requester_user_id=? AND product_id=? AND status IN ('Approvata','Applicata')
                      AND ABS(requested_price-?) < 0.001
                    ORDER BY id DESC LIMIT 1""",
                    (session.get('user_id'),p['id'],unit_price)).fetchone()
                if used_req:
                    used_discount_request_ids.append(used_req['id'])
            db.execute("UPDATE products SET quantity=quantity-? WHERE id=?",(qty,p["id"]))
            db.execute("INSERT INTO sales(user_id,username,product_id,product_code,quantity,unit_price,sale_number,payment_method,channel,status,original_unit_price,discount_reason,authorized_by_user_id,authorized_by_username) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",(session.get("user_id"),session.get("user","sconosciuto"),p["id"],p["brand_code"],qty,unit_price,sale_number,payment,channel,"Confermata",p["price"],pd["reason"],pd["authorized_by_user_id"],pd["authorized_by_username"]))
            add_reorder_quantity(db,p["id"],qty)
            log_action(db,"Vendita da carrello",p,f"{sale_number}; {channel}; {payment}; pezzi: {qty}; listino € {p['price']:.2f}; venduto € {unit_price:.2f}; autorizzato da {pd['authorized_by_username'] or '-'}")
            total+=qty*unit_price; pieces+=qty
        first_sale=db.execute("SELECT MIN(id) FROM sales WHERE sale_number=?",(sale_number,)).fetchone()[0]
        _notify_roles(db,('admin','manager'),'sale','Nuova vendita',f"{session.get('user','sconosciuto')} · {pieces} articoli · € {total:.2f} · {payment}",'sale',first_sale,f"sale:{first_sale}")
        if session.get('role') == 'seller':
            for discount_request_id in set(used_discount_request_ids):
                db.execute("""UPDATE notifications
                              SET read_at=COALESCE(read_at,CURRENT_TIMESTAMP),
                                  archived_at=COALESCE(archived_at,CURRENT_TIMESTAMP),
                                  archived_by_user_id=?, archived_by_username=?
                              WHERE recipient_user_id=? AND reference_type='discount' AND reference_id=? AND archived_at IS NULL""",
                           (session.get('user_id'),session.get('user'),session.get('user_id'),discount_request_id))
        db.commit()
    session.pop("cart",None); session.pop("cart_prices",None); session.modified=True
    flash(f"Vendita {sale_number} confermata: {pieces} articoli · € {total:.2f}.")
    return redirect(url_for("pos"))

@app.route("/products/<int:product_id>/qr", methods=["GET", "POST"])
@role_required("admin","manager")
def product_qr_pdf(product_id):
    """Configura e genera etichette QR pieghevoli da applicare ai gioielli."""
    with connect() as db:
        p=db.execute("SELECT * FROM products WHERE id=?",(product_id,)).fetchone()
        if not p:
            flash("Prodotto non trovato.")
            return redirect(url_for("products"))

    payload=(p["brand_code"] or "").strip()
    if not payload:
        flash("Il prodotto non ha un codice interno valido.")
        return redirect(url_for("product_detail",product_id=product_id))

    if request.method == "GET":
        default_quantity=max(1, int(p["quantity"] or 1))
        body=r"""
        <style>
          .label-config{max-width:760px;margin:auto}
          .label-preview-wrap{display:grid;grid-template-columns:minmax(280px,1fr) minmax(260px,1fr);gap:24px;align-items:start}
          .fold-label{width:200px;height:300px;max-width:100%;border:2px dashed #9ca3af;background:#fff;display:flex;align-items:center;justify-content:center;position:relative;margin:18px auto;box-sizing:border-box}
          .fold-label:after{display:none}
          .qr-demo{display:flex;align-items:center;justify-content:center;padding:8px}
          .qr-box{width:150px;height:150px;background:repeating-conic-gradient(#111 0 25%,#fff 0 50%) 50%/14px 14px;border:5px solid #fff;outline:1px solid #111}
          .tail-demo{display:flex;align-items:center;justify-content:center;color:#6b7280;font-size:13px;text-align:center;padding:8px}
          .measure{font-size:13px;color:#6b7280;text-align:center}
          .help-list{line-height:1.7;margin:8px 0 0 18px}
          .field-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}
          @media(max-width:760px){.label-preview-wrap,.field-grid{grid-template-columns:1fr}.fold-label{width:270px;height:90px}}
        </style>
        <p><a href="{{url_for('product_detail',product_id=p.id)}}">← Torna al prodotto</a></p>
        <div class="card label-config">
          <h1>Etichette QR prodotti</h1>
          <p class="muted">Etichette prodotto da ritagliare: area 20 × 30 mm con QR 15 × 15 mm, senza testo.</p>
          <div class="label-preview-wrap">
            <div>
              <h3>{{p.model_name or p.brand_code}}</h3>
              <p>
                <b>Codice interno:</b> {{p.brand_code}}<br>
                <b>Categoria:</b> {{p.category or '-'}}<br>
                <b>Materiale:</b> {{p.material or '-'}}<br>
                <b>Disponibilità:</b> {{p.quantity}}
              </p>
              <form method="post">
                <div class="field-grid">
                  <label>Numero di etichette
                    <input type="number" name="quantity" min="1" max="500" value="{{default_quantity}}" required>
                  </label>
                  <label>Prima posizione del foglio
                    <input type="number" name="start_position" min="1" max="70" value="1" required>
                  </label>
                </div>
                <p class="muted">Un foglio contiene 70 posizioni. Usa la posizione iniziale quando il foglio è già parzialmente utilizzato.</p>
                <button type="submit">Genera PDF etichette</button>
              </form>
            </div>
            <div>
              <h3>Anteprima reale</h3>
              <div class="fold-label"><div class="qr-demo"><div class="qr-box" aria-label="Anteprima QR"></div></div></div>
              <div class="measure">Area di ritaglio 20 × 30 mm · QR 15 × 15 mm · nessun testo</div>
              <ol class="help-list"><li>Stampa in scala reale al 100%.</li><li>Ritaglia lungo il bordo tratteggiato.</li></ol>
            </div>
          </div>
        </div>
        """
        return page("Etichette QR",body,p=p,default_quantity=default_quantity)

    try:
        quantity=int(request.form.get("quantity","1"))
        start_position=int(request.form.get("start_position","1"))
    except (TypeError, ValueError):
        flash("Quantità o posizione iniziale non valida.")
        return redirect(url_for("product_qr_pdf",product_id=product_id))

    if quantity < 1 or quantity > 500:
        flash("Puoi generare da 1 a 500 etichette per volta.")
        return redirect(url_for("product_qr_pdf",product_id=product_id))
    if start_position < 1 or start_position > 70:
        flash("La posizione iniziale deve essere compresa tra 1 e 70.")
        return redirect(url_for("product_qr_pdf",product_id=product_id))

    buffer=BytesIO()
    page_w,page_h=A4
    c=canvas.Canvas(buffer,pagesize=A4)

    columns=7
    rows=10
    per_page=columns*rows
    pitch_x=28*mm
    pitch_y=28*mm
    label_w=20*mm
    label_h=30*mm
    qr_size=15*mm

    grid_w=columns*pitch_x
    grid_h=rows*pitch_y
    origin_x=(page_w-grid_w)/2
    origin_y=(page_h-grid_h)/2

    def draw_fold_label(slot_index):
        col=slot_index % columns
        row=slot_index // columns
        cell_x=origin_x+col*pitch_x
        cell_top=page_h-origin_y-row*pitch_y
        label_x=cell_x+(pitch_x-label_w)/2
        label_y=cell_top-(pitch_y+label_h)/2

        c.saveState()
        c.setStrokeColor(colors.HexColor("#9CA3AF"))
        c.setLineWidth(0.45)
        c.setDash(1.5,1.2)
        c.rect(label_x,label_y,label_w,label_h,stroke=1,fill=0)

        c.restoreState()

        qr_widget=qr.QrCodeWidget(payload)
        qr_widget.barLevel="H"
        bounds=qr_widget.getBounds()
        qr_width=bounds[2]-bounds[0]
        qr_height=bounds[3]-bounds[1]
        scale=qr_size/max(qr_width,qr_height)
        drawing=Drawing(qr_size,qr_size,transform=[scale,0,0,scale,0,0])
        drawing.add(qr_widget)

        qr_x=label_x+(label_w-qr_size)/2
        qr_y=label_y+(label_h-qr_size)/2
        renderPDF.draw(drawing,c,qr_x,qr_y)

    remaining=quantity
    first_page=True
    position=start_position-1

    while remaining > 0:
        if not first_page:
            position=0

        available=per_page-position
        count=min(remaining,available)

        for offset in range(count):
            draw_fold_label(position+offset)

        c.setFont("Helvetica",6.5)
        c.setFillColor(colors.HexColor("#6B7280"))
        c.drawCentredString(page_w/2,7*mm,"Stampa in dimensione reale / scala 100% · Etichette 20 x 30 mm · QR 15 x 15 mm")
        c.showPage()

        remaining-=count
        first_page=False

    c.save()
    buffer.seek(0)

    safe_code="".join(ch if ch.isalnum() or ch in "-_" else "_" for ch in payload)
    filename=f"Etichette_QR_{safe_code}_{quantity}.pdf"
    return send_file(buffer,mimetype="application/pdf",as_attachment=False,download_name=filename)

@app.post("/products/<int:product_id>/stock")
@login_required
def change_stock(product_id):
    try: d=int(request.form["delta"])
    except (KeyError,ValueError): flash("Operazione non valida."); return redirect(url_for("products"))
    if d != 1:
        flash("La vendita diretta è disattivata: aggiungi il prodotto al carrello e completa la vendita dalla Cassa.")
        return redirect(request.referrer or url_for("products"))
    if session.get("role") not in ("admin","manager"):
        flash("Solo Admin e Gestore possono caricare merce."); return redirect(request.referrer or url_for("products"))
    with connect() as db:
        p=db.execute("SELECT * FROM products WHERE id=?",(product_id,)).fetchone()
        if p:
            db.execute("UPDATE products SET quantity=quantity+1 WHERE id=?",(product_id,))
            log_action(db,"Merce caricata",p,f"Quantità: {p['quantity']} → {p['quantity']+1}")
            db.commit(); flash("Quantità aggiornata.")
        else:
            flash("Prodotto non trovato.")
    return redirect(request.referrer or url_for("products"))

@app.post("/products/<int:product_id>/toggle-active")
@role_required("admin","manager")
def toggle_product_active(product_id):
    with connect() as db:
        p=db.execute("SELECT * FROM products WHERE id=?",(product_id,)).fetchone()
        if not p: flash("Prodotto non trovato.")
        else:
            active=0 if p["active"] else 1
            db.execute("UPDATE products SET active=? WHERE id=?",(active,product_id))
            log_action(db,"Prodotto riattivato" if active else "Prodotto archiviato",p)
            db.commit(); flash("Prodotto riattivato." if active else "Prodotto archiviato e nascosto dalla boutique.")
    return redirect(request.referrer or url_for("products"))

@app.post("/products/<int:product_id>/duplicate")
@role_required("admin","manager")
def duplicate_product(product_id):
    with connect() as db:
        p=db.execute("SELECT * FROM products WHERE id=?",(product_id,)).fetchone()
        if not p: flash("Prodotto non trovato."); return redirect(url_for("products"))
        brand=p["brand_code"]+"-COPIA"; supplier=p["supplier_code"]+"-COPIA"; n=2
        while db.execute("SELECT 1 FROM products WHERE brand_code=? OR supplier_code=?",(brand,supplier)).fetchone():
            brand=p["brand_code"]+f"-COPIA-{n}"; supplier=p["supplier_code"]+f"-COPIA-{n}"; n+=1
        cur=db.execute("""INSERT INTO products(supplier_code,brand_code,quantity,price,category,photo_data,material,color,size,stone,thread_type,notes,active,min_stock,location,cost_price,is_new,is_bestseller,model_name,variant_group) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,1,?,?,?,?,?,?,?)""",(supplier,brand,0,p["price"],p["category"],p["photo_data"],p["material"],p["color"],p["size"],p["stone"],p["thread_type"],p["notes"],p["min_stock"],p["location"],p["cost_price"],p["is_new"],p["is_bestseller"],p["model_name"],p["variant_group"]))
        new_id=cur.lastrowid; np=db.execute("SELECT * FROM products WHERE id=?",(new_id,)).fetchone(); log_action(db,"Prodotto duplicato",np,f"Da {p['brand_code']}"); db.commit()
    flash("Copia creata: completa i codici e la quantità.")
    return redirect(url_for("edit_product",product_id=new_id))

@app.route("/boutique/ordina/<int:catalog_id>",methods=["GET","POST"])
def public_catalog_order(catalog_id):
    with connect() as db: c=db.execute("SELECT * FROM supplier_catalog WHERE id=? AND active=1 AND excluded=0",(catalog_id,)).fetchone()
    if not c: return redirect(url_for("boutique"))
    if request.method=="POST":
        name=request.form.get("customer_name","").strip(); phone=request.form.get("customer_phone","").strip(); notes=request.form.get("notes","").strip()
