@app.get("/admin/backup")
@role_required("admin")
def backup_database():
    if not os.path.exists(DB_PATH):
        flash("Database non trovato.")
        return redirect(url_for("dashboard"))
    stamp = now_rome().strftime("%Y%m%d_%H%M%S")
    backup_path = os.path.join(BACKUP_DIR, f"gestionale_tbs_backup_{stamp}.db")
    make_consistent_backup(backup_path)
    with connect() as db:
        log_action(db, "Backup database", details=os.path.basename(backup_path))
        db.commit()
    return send_file(backup_path, as_attachment=True, download_name=os.path.basename(backup_path), mimetype="application/octet-stream")

@app.route("/admin/system-status", methods=["GET", "POST"])
@role_required("admin")
def system_status():
    if request.method == "POST":
        upload = request.files.get("database")
        if not upload or not upload.filename:
            flash("Seleziona un file .db da ripristinare.")
            return redirect(url_for("system_status"))
        temp_fd, temp_path = tempfile.mkstemp(prefix="tbs_restore_", suffix=".db")
        os.close(temp_fd)
        try:
            upload.save(temp_path)
            valid, detail = database_integrity(temp_path)
            if not valid:
                flash(f"Ripristino annullato: database non valido ({detail}).")
                return redirect(url_for("system_status"))
            safety = os.path.join(BACKUP_DIR, f"prima_ripristino_{now_rome().strftime('%Y%m%d_%H%M%S')}.db")
            if os.path.exists(DB_PATH):
                make_consistent_backup(safety)
            os.replace(temp_path, DB_PATH)
            init_db()
            flash("Database ripristinato correttamente. È stato creato anche un backup di sicurezza.")
            return redirect(url_for("system_status"))
        finally:
            if os.path.exists(temp_path):
                os.remove(temp_path)

    valid, integrity = database_integrity(DB_PATH)
    with connect() as db:
        counts = {}
        for table in ("users", "products", "sales", "customer_orders", "supplier_orders", "supplier_catalog"):
            try:
                counts[table] = db.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0]
            except sqlite3.Error:
                counts[table] = 0
    backups = sorted(Path(BACKUP_DIR).glob("*.db"), key=lambda x: x.stat().st_mtime, reverse=True)
    last_backup = datetime.fromtimestamp(backups[0].stat().st_mtime, tz=ROME_TZ).strftime("%d/%m/%Y %H:%M") if backups else None
    size_mb = os.path.getsize(DB_PATH) / (1024 * 1024) if os.path.exists(DB_PATH) else 0
    storage = "Temporaneo (/tmp)" if DB_IS_EPHEMERAL else "Persistente (/var/data)"
    body = '''<h1>Stato del sistema</h1>
    <div class="grid">
      <div class="card" style="background:{{'#e8fff0' if valid else '#fff0f0'}}!important;border:2px solid {{'#15803d' if valid else '#b91c1c'}}!important;color:#111!important"><div style="color:#333;font-weight:800">Database</div><div class="metric" style="color:{{'#116329' if valid else '#991b1b'}}!important;font-weight:950!important">{{ "OK" if valid else "ERRORE" }}</div><p style="color:#111!important;font-weight:700">{{ integrity }}</p></div>
      <div class="card"><div class="muted">Archiviazione</div><div class="metric" style="font-size:22px">{{ storage }}</div><p class="muted">{{ db_path }}</p></div>
      <div class="card"><div class="muted">Versione</div><div class="metric" style="font-size:22px">{{ version }}</div><p>{{ "%.2f"|format(size_mb) }} MB</p></div>
      <div class="card"><div class="muted">Ultimo backup locale</div><div class="metric" style="font-size:22px">{{ last_backup or "Non presente" }}</div></div>
    </div>
    <div class="card"><h3>Contenuto</h3><p>Utenti: <b>{{ counts.users }}</b> · Prodotti: <b>{{ counts.products }}</b> · Vendite: <b>{{ counts.sales }}</b> · Ordini clienti: <b>{{ counts.customer_orders }}</b> · Ordini fornitore: <b>{{ counts.supplier_orders }}</b> · Catalogo: <b>{{ counts.supplier_catalog }}</b></p></div>
    {% if ephemeral %}<div class="card" style="border-left:5px solid #b45309"><h3>Intervento necessario</h3><p>Il database si trova in <code>/tmp</code>: Render può cancellarlo durante riavvii o deploy. Prima di usare questa versione in produzione configura un disco persistente montato su <code>/var/data</code>, oppure imposta <code>DATABASE_PATH</code> verso uno spazio persistente.</p></div>{% endif %}
    <div class="card"><h3>Backup e ripristino</h3>{% if not ephemeral %}<p><b>Protezione attiva:</b> database e backup locali sono salvati sul disco persistente.</p>{% endif %}<p><a href="{{ url_for('backup_database') }}">Scarica backup verificato</a></p><form method="post" enctype="multipart/form-data" onsubmit="return confirm('Confermi il ripristino? Il database attuale sarà salvato prima della sostituzione.')"><label>Ripristina un backup SQLite</label><input type="file" name="database" accept=".db,.sqlite,.sqlite3" required><button class="secondary">Verifica e ripristina</button></form></div>'''
    return page("Stato sistema", body, valid=valid, integrity=integrity, storage=storage, db_path=DB_PATH, version=APP_VERSION, size_mb=size_mb, last_backup=last_backup, counts=counts, ephemeral=DB_IS_EPHEMERAL)

@app.get("/sales")
@role_required("admin","manager")
def sales_log():
    user_filter=request.args.get("user","").strip()
    code_filter=request.args.get("code","").strip().upper()
    sql="SELECT * FROM sales WHERE 1=1"; params=[]
    if user_filter:
        sql+=" AND username LIKE ?"; params.append(f"%{user_filter}%")
    if code_filter:
        sql+=" AND product_code LIKE ?"; params.append(f"%{code_filter}%")
    sql+=" ORDER BY id DESC LIMIT 500"
    with connect() as db:
        rows=db.execute(sql,params).fetchall()
        total_qty=sum(x["quantity"] for x in rows if x["status"]=="Confermata")
        total_value=sum(x["quantity"]*x["unit_price"] for x in rows if x["status"]=="Confermata")
    return page("Vendite",'''<h1>Registro vendite</h1><div class="card"><form class="inline" method="get"><input name="user" value="{{user_filter}}" placeholder="Venditore"><input name="code" value="{{code_filter}}" placeholder="Codice prodotto"><button>Filtra</button></form></div><div class="grid"><div class="card"><div class="muted">Pezzi registrati</div><div class="metric">{{total_qty}}</div></div><div class="card"><div class="muted">Valore registrato</div><div class="metric">€ {{'%.2f'|format(total_value)}}</div></div></div><div class="card">{% if rows %}{% for x in rows %}<div style="display:flex;gap:14px;justify-content:space-between;align-items:flex-start;flex-wrap:wrap"><p style="margin:0"><b>{{x.sale_number or '-'}}</b> · {{x.created_at|rome_time}} · {{x.username}}<br><b>{{x.product_code}}</b> · {{x.quantity}} pz · € {{'%.2f'|format(x.unit_price)}} cad. · {{x.payment_method or 'Altro'}} · {{x.channel or 'Negozio'}}{% if x.status=='Stornata' %}<br><span class="badge" style="background:#f8d7da;color:#8a1c26">STORNATA</span> <span class="muted">da {{x.reversed_by_username}} · {{x.reversed_at|rome_time}} · {{x.reversal_reason or ''}}</span>{% endif %}{% if x.corrected_at %}<br><span class="badge">Prezzo corretto</span> <span class="muted">da {{x.corrected_by_username}} · {{x.corrected_at|rome_time}}{% if x.correction_reason %} · {{x.correction_reason}}{% endif %}</span>{% endif %}</p><div class="inline"><a class="secondary" style="text-decoration:none;padding:9px 12px;border-radius:9px" href="{{url_for('edit_sale',sale_id=x.id)}}">Modifica prezzo</a>{% if x.status=='Confermata' %}<form method="post" action="{{url_for('reverse_sale',sale_id=x.id)}}" onsubmit="const r=prompt('Motivo dello storno:'); if(!r)return false; this.reason.value=r; return confirm('Confermi lo storno? Verranno ripristinati quantità e disponibilità.');"><input type="hidden" name="reason"><button class="danger">Storna</button></form>{% endif %}</div></div><hr>{% endfor %}{% else %}<p>Nessuna vendita registrata.</p>{% endif %}</div>''',rows=rows,user_filter=user_filter,code_filter=code_filter,total_qty=total_qty,total_value=total_value)

@app.post("/sales/<int:sale_id>/reverse")
@role_required("admin","manager")
def reverse_sale(sale_id):
    reason=(request.form.get("reason") or "").strip()
    if not reason:
        flash("Indica il motivo dello storno."); return redirect(url_for("sales_log"))
    with connect() as db:
        sale=db.execute("SELECT * FROM sales WHERE id=?",(sale_id,)).fetchone()
        if not sale:
            flash("Vendita non trovata.")
        elif sale["status"]!="Confermata":
            flash("Questa vendita è già stata stornata o non è stornabile.")
        else:
            db.execute("UPDATE products SET quantity=quantity+?,active=1 WHERE id=?",(sale["quantity"],sale["product_id"]))
            db.execute("UPDATE reorder_pending SET quantity=MAX(0,quantity-?) WHERE product_id=?",(sale["quantity"],sale["product_id"]))
            db.execute("UPDATE sales SET status='Stornata',reversed_at=CURRENT_TIMESTAMP,reversed_by_user_id=?,reversed_by_username=?,reversal_reason=? WHERE id=?",(session.get("user_id"),session.get("user","sconosciuto"),reason,sale_id))
            product=db.execute("SELECT * FROM products WHERE id=?",(sale["product_id"],)).fetchone()
            log_action(db,"Vendita stornata",product,f"{sale['sale_number'] or '-'}; {sale['product_code']}; {sale['quantity']} pz; € {sale['unit_price']*sale['quantity']:.2f}; motivo: {reason}")
            db.commit(); flash("Vendita stornata: incasso annullato e quantità ripristinata.")
    return redirect(url_for("sales_log"))

@app.route("/sales/<int:sale_id>/edit", methods=["GET","POST"])
@role_required("admin","manager")
def edit_sale(sale_id):
    with connect() as db:
        sale=db.execute("SELECT * FROM sales WHERE id=?",(sale_id,)).fetchone()
        if not sale:
            flash("Vendita non trovata.")
            return redirect(url_for("sales_log"))
        if request.method=="POST":
            raw=(request.form.get("unit_price") or "").strip().replace(",",".")
            reason=(request.form.get("reason") or "").strip()
            try:
                new_price=round(float(raw),2)
            except ValueError:
                flash("Inserisci un prezzo valido.")
                return redirect(url_for("edit_sale",sale_id=sale_id))
            if new_price < 0:
                flash("Il prezzo non può essere negativo.")
                return redirect(url_for("edit_sale",sale_id=sale_id))
            if not reason:
                flash("Indica il motivo della modifica.")
                return redirect(url_for("edit_sale",sale_id=sale_id))
            old_price=float(sale["unit_price"] or 0)
            original_price=sale["original_unit_price"]
            if original_price is None:
                original_price=old_price
            db.execute("""UPDATE sales SET unit_price=?, original_unit_price=?, correction_reason=?, corrected_at=CURRENT_TIMESTAMP, corrected_by_user_id=?, corrected_by_username=? WHERE id=?""",
                       (new_price,original_price,reason,session.get("user_id"),session.get("user","sconosciuto"),sale_id))
            product=db.execute("SELECT * FROM products WHERE id=?",(sale["product_id"],)).fetchone()
            log_action(db,"Prezzo vendita corretto",product,
                       f"{sale['sale_number'] or '-'}; {sale['product_code']}; € {old_price:.2f} → € {new_price:.2f}; motivo: {reason}")
            try:
                created=str(sale["created_at"] or "").replace("Z","+00:00")
                dt=datetime.fromisoformat(created)
                if dt.tzinfo is None:
                    dt=dt.replace(tzinfo=timezone.utc)
                sale_day=dt.astimezone(ROME_TZ).date()
                if db.execute("SELECT 1 FROM treasury_daily_closures WHERE closure_date=?",(sale_day.isoformat(),)).fetchone():
                    db.execute("DELETE FROM treasury_daily_closures WHERE closure_date=?",(sale_day.isoformat(),))
                    create_daily_closure(db,sale_day)
            except Exception as exc:
                print(f"Chiusura non rigenerata dopo correzione vendita {sale_id}: {exc}")
            db.commit()
            flash(f"Prezzo aggiornato da € {old_price:.2f} a € {new_price:.2f}.")
            return redirect(url_for("sales_log"))
    return page("Modifica vendita",'''<h1>Modifica prezzo vendita</h1><div class="card" style="max-width:650px"><p><b>Vendita:</b> {{sale.sale_number or '-'}}<br><b>Articolo:</b> {{sale.product_code}}<br><b>Venditore:</b> {{sale.username}}<br><b>Data:</b> {{sale.created_at|rome_time}}<br><b>Quantità:</b> {{sale.quantity}}</p><form method="post" onsubmit="return confirm('Confermi la modifica del prezzo di questa vendita?')"><label>Prezzo unitario corretto (€)</label><input name="unit_price" type="number" min="0" step="0.01" value="{{'%.2f'|format(sale.unit_price)}}" required autofocus><label>Motivo della correzione</label><textarea name="reason" required placeholder="Esempio: sconto concordato non registrato nella vendita rapida">{{sale.correction_reason or ''}}</textarea><div class="inline" style="margin-top:14px"><button class="success">Salva correzione</button><a class="secondary" style="text-decoration:none;padding:11px 14px;border-radius:9px" href="{{url_for('sales_log')}}">Annulla</a></div></form><p class="muted">Il prezzo di listino del prodotto non viene modificato. La correzione resta registrata nello storico.</p></div>''',sale=sale)

@app.route("/reorders",methods=["GET","POST"])
@role_required("admin","manager")
def reorders():
    if request.method=="POST":
        with connect() as db:
            for key,value in request.form.items():
                if not key.startswith("qty_"): continue
                try: product_id=int(key[4:]); qty=max(0,int(value))
                except ValueError: continue
                db.execute("INSERT INTO reorder_pending(product_id,quantity) VALUES(?,?) ON CONFLICT(product_id) DO UPDATE SET quantity=excluded.quantity",(product_id,qty))
            log_action(db,"Proposta riordino aggiornata"); db.commit()
        flash("Quantità aggiornate."); return redirect(url_for("reorders"))
    with connect() as db:
        rows=db.execute("SELECT p.id,p.brand_code,p.supplier_code,p.quantity AS stock,COALESCE(r.quantity,0) AS reorder_qty FROM products p JOIN reorder_pending r ON r.product_id=p.id WHERE r.quantity>0 ORDER BY p.supplier_code").fetchall()
        customer_rows=db.execute("SELECT supplier_code,brand_code,SUM(quantity) reorder_qty,COUNT(*) customers FROM supplier_catalog_requests WHERE status='Accettato' GROUP BY supplier_code,brand_code ORDER BY supplier_code").fetchall()
        history=db.execute("SELECT o.*,COUNT(i.id) lines,COALESCE(SUM(i.quantity),0) pieces,COALESCE(SUM(i.received_quantity),0) received FROM supplier_orders o LEFT JOIN supplier_order_items i ON i.order_id=o.id GROUP BY o.id ORDER BY o.id DESC LIMIT 30").fetchall()
    body="""<h1>🚚 Riordini fornitore</h1><div class='card'><h2>Prossimo PDF</h2><p class='muted'>Comprende scorte da reintegrare e ordini cliente accettati. Dopo la generazione, gli ordini cliente passano a “Ordinato” e non saranno duplicati.</p>{% for x in rows %}<p><b>{{x.supplier_code}}</b> · {{x.brand_code}} · magazzino {{x.stock}} · <b>{{x.reorder_qty}} pz</b></p>{% endfor %}{% for x in customer_rows %}<p><b>{{x.supplier_code}}</b> · {{x.brand_code}} · <b>{{x.reorder_qty}} pz clienti</b> · {{x.customers}} richieste</p>{% endfor %}{% if rows or customer_rows %}<form method='post' action='{{url_for("generate_reorder_pdf")}}' onsubmit='return confirm("Generare e archiviare il PDF?")'><button class='success'>📄 Genera PDF e segna ordinato</button></form>{% else %}<p>Nessun articolo da ordinare.</p>{% endif %}</div><div class='card'><h2>Storico fornitori e ricezioni</h2>{% for o in history %}<div style='border-bottom:1px solid #ddd;padding:12px 0'><b>{{o.order_number}}</b> · {{o.status}} · {{o.received}}/{{o.pieces}} pezzi · {{o.created_at|rome_time}}{% if o.status!='Ricevuto' %}<p><a class='secondary' style='display:inline-block;text-decoration:none;padding:9px 12px;border-radius:8px' href='{{url_for("receive_order_detail",order_id=o.id)}}'>Spunta merce arrivata</a></p>{% endif %}</div>{% else %}<p>Nessun ordine generato.</p>{% endfor %}</div>"""
    return page("Riordini",body,rows=rows,customer_rows=customer_rows,history=history)

@app.post("/reorders/pdf")
@role_required("admin","manager")
def generate_reorder_pdf():
    with connect() as db:
        stock=db.execute("SELECT p.id,p.supplier_code,COALESCE(r.quantity,0) reorder_qty FROM products p JOIN reorder_pending r ON r.product_id=p.id WHERE r.quantity>0").fetchall()
        customers=db.execute("SELECT * FROM supplier_catalog_requests WHERE status='Accettato' ORDER BY supplier_code,id").fetchall()
        if not stock and not customers:
            flash("Nessun articolo da inserire nel PDF."); return redirect(url_for("reorders"))
        totals={}
        for x in stock: totals[x['supplier_code']]=totals.get(x['supplier_code'],0)+x['reorder_qty']
        for x in customers: totals[x['supplier_code']]=totals.get(x['supplier_code'],0)+x['quantity']
        order_number=next_order_number(db)
        cur=db.execute("INSERT INTO supplier_orders(order_number,status,created_by) VALUES(?,'Ordinato',?)",(order_number,session.get("user","sconosciuto")))
        oid=cur.lastrowid
        for x in stock:
            db.execute("INSERT INTO supplier_order_items(order_id,product_id,supplier_code,quantity) VALUES(?,?,?,?)",(oid,x['id'],x['supplier_code'],x['reorder_qty']))
            db.execute("UPDATE reorder_pending SET quantity=0 WHERE product_id=?",(x['id'],))
        for x in customers:
            db.execute("INSERT INTO supplier_order_items(order_id,product_id,supplier_code,quantity,catalog_request_id) VALUES(?,0,?,?,?)",(oid,x['supplier_code'],x['quantity'],x['id']))
            db.execute("UPDATE supplier_catalog_requests SET status='Ordinato',supplier_order_id=?,ordered_at=CURRENT_TIMESTAMP WHERE id=?",(oid,x['id']))
            db.execute("INSERT INTO catalog_request_events(request_id,event_type,username,details) VALUES(?,?,?,?)",(x['id'],'Ordinato',session.get('user','sconosciuto'),order_number))
        log_action(db,"PDF ordine fornitore generato",details=f"{order_number}; {sum(totals.values())} pezzi"); db.commit()
    buffer=BytesIO(); pdf=canvas.Canvas(buffer,pagesize=A4); width,height=A4; y=height-55
    pdf.setTitle(order_number); pdf.setFont("Helvetica-Bold",16); pdf.drawString(45,y,"ORDINE FORNITORE"); y-=25
    pdf.setFont("Helvetica",10); pdf.drawString(45,y,f"Ordine: {order_number}"); pdf.drawRightString(width-45,y,now_rome().strftime("%d/%m/%Y")); y-=32
    pdf.setFont("Helvetica-Bold",11); pdf.drawString(45,y,"CODICE FORNITORE"); pdf.drawRightString(width-45,y,"QUANTITA"); y-=10; pdf.line(45,y,width-45,y); y-=20
    pdf.setFont("Helvetica",11)
    for code,qty in sorted(totals.items()):
        if y<55:
            pdf.showPage(); y=height-55; pdf.setFont("Helvetica",11)
        pdf.drawString(45,y,str(code)); pdf.drawRightString(width-45,y,str(qty)); y-=20
    pdf.save(); buffer.seek(0)
    return send_file(buffer,as_attachment=True,download_name=f"{order_number}.pdf",mimetype="application/pdf")

@app.route("/reorders/<int:order_id>/receive",methods=["GET","POST"])
@role_required("admin","manager")
def receive_order_detail(order_id):
    with connect() as db:
        order=db.execute("SELECT * FROM supplier_orders WHERE id=?",(order_id,)).fetchone()
        if not order:
            flash("Ordine non trovato."); return redirect(url_for("reorders"))
        if request.method=='POST':
            for key,value in request.form.items():
                if not key.startswith('arrived_'): continue
                try: item_id=int(key[8:]); arrived=max(0,int(value))
                except ValueError: continue
                item=db.execute("SELECT * FROM supplier_order_items WHERE id=? AND order_id=?",(item_id,order_id)).fetchone()
                if not item: continue
                new=min(item['quantity'],item['received_quantity']+arrived)
                delta=new-item['received_quantity']
                if delta<=0: continue
                db.execute("UPDATE supplier_order_items SET received_quantity=? WHERE id=?",(new,item_id))
                if item['catalog_request_id']:
                    req=db.execute("SELECT * FROM supplier_catalog_requests WHERE id=?",(item['catalog_request_id'],)).fetchone()
                    rq=min(req['quantity'],req['received_quantity']+delta)
                    status='Arrivato' if rq>=req['quantity'] else 'Arrivato parzialmente'
                    db.execute("UPDATE supplier_catalog_requests SET received_quantity=?,status=? WHERE id=?",(rq,status,req['id']))
                    db.execute("INSERT INTO catalog_request_events(request_id,event_type,username,details) VALUES(?,?,?,?)",(req['id'],status,session.get('user','sconosciuto'),f"Ricevuti {rq}/{req['quantity']}"))
                elif item['product_id']:
                    db.execute("UPDATE products SET quantity=quantity+? WHERE id=?",(delta,item['product_id']))
            remaining=db.execute("SELECT COUNT(*) FROM supplier_order_items WHERE order_id=? AND received_quantity<quantity",(order_id,)).fetchone()[0]
            db.execute("UPDATE supplier_orders SET status=?,received_at=CASE WHEN ?=0 THEN CURRENT_TIMESTAMP ELSE received_at END WHERE id=?",('Ricevuto' if remaining==0 else 'Ricevuto parzialmente',remaining,order_id))
            log_action(db,"Ricezione ordine fornitore",details=order['order_number']); db.commit(); flash("Ricezione aggiornata.")
            return redirect(url_for('receive_order_detail',order_id=order_id))
        items=db.execute("SELECT i.*,r.customer_name,r.customer_phone,r.brand_code FROM supplier_order_items i LEFT JOIN supplier_catalog_requests r ON r.id=i.catalog_request_id WHERE i.order_id=? ORDER BY i.supplier_code,i.id",(order_id,)).fetchall()
    body="""<h1>📥 Ricezione {{order.order_number}}</h1><p class='muted'>Inserisci solo i pezzi arrivati adesso. Puoi tornare più volte finché l’ordine è completo.</p><div class='card'><form method='post'>{% for i in items %}<div style='display:grid;grid-template-columns:1fr 110px;gap:12px;align-items:center;border-bottom:1px solid #ddd;padding:12px 0'><div><b>{{i.supplier_code}}</b> · {{i.received_quantity}}/{{i.quantity}} ricevuti{% if i.customer_name %}<br><span class='muted'>Cliente: {{i.customer_name}} · {{i.customer_phone}} · {{i.brand_code}}</span>{% else %}<br><span class='muted'>Ripristino magazzino</span>{% endif %}</div><input name='arrived_{{i.id}}' type='number' min='0' max='{{i.quantity-i.received_quantity}}' value='0'></div>{% endfor %}<button class='success' style='margin-top:15px'>Salva pezzi arrivati</button></form></div>"""
    return page("Ricezione merce",body,order=order,items=items)

